(window.GIM_TS=window.GIM_TS||{})["Nazir.1"]={"from":24,"a":[["\u0003אם תמצי\u0004 \u0005[תרצה\u0006\u0005]\u0006 \u0003לומר\u0004 במקרה שקיבל עליו נזירות לאחר עשרים יום וחזר וקיבל עליו \u0003נזירות מועטת\u0004 של שלושים יום מעכשיו, \u0003כיון\u0004 ש\u0003עשרה יומין\u0004 \u0005[ימים\u0006\u0005]\u0006 \u0003הוא דיתרין\u0004 \u0005[שנשארים\u0006\u0005]\u0006 לבסוף \u0003לא סליק ליה הלין\u0004 \u0005[יעלו לו אותם\u0006\u0005]\u0006 \u0003עשרה\u0004 אחרונים לכלל נזירות שלימה, שכן אין בהם כדי גידול שיער. ועליו לנהוג נזירות שלימה של שלושים יום לאחר הנזירות השניה, ומשום כך אין הנזירות חלה בעשרים יום הראשונים, יש לשאול: \u0003ודאי נזיר מאה יום, כיון דאית ליה\u0004 \u0005[שיש לו\u0006\u0005]\u0006 עוד \u0003תמנין יומין\u0004 \u0005[שמונים יום\u0006\u0005]\u0006 \u0003לבסוף,\u0004 האם \u0003סלקין ליה\u0004 \u0005[עולים לו\u0006\u0005]\u0006 עשרים הימים הראשונים לכלל נזירות המאה, \u0003או לא?\u0004","ומתוך שאלה זו עולה שאלה אחרת: \u0003ואם תמצי\u0004 \u0005[תרצה\u0006\u0005]\u0006 \u0003לומר\u0004 כי \u0003חיילי\u0004 \u0005[חלים\u0006\u0005]\u0006 ימי הנזירות הראשונה, ומשלימים אותם בשמונים ימים לאחר ימי נזירות שניה, יש לשאול: אם \u0003אמר \"הריני נזיר לאחר עשרים יום ומעכשיו\u0004 אני \u0003נזיר עולם\", מהו\u0004 הדין? \u0003מי חיילא עליה\u0004 \u0005[האם חלה עליו\u0006\u0005]\u0006 נזירות עולם באותם עשרים יום, \u0003או לא?\u0004 שהרי לנזירות עולם אין כלל גבול מוגדר, שנוכל לומר שישלים את מותר ימיה לאחר הנזירות השניה, ואם כן יש לומר שאינו מקבל על עצמו נזירות באותם ימים.","\u0003אם תמצי\u0004 \u0005[תרצה\u0006\u0005]\u0006 \u0003לומר: הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 במקרים שמקבל על עצמו נזירות סתם לאחר עשרים יום \u0003כיון\u0004 ש\u0003אפשר לאיתשולי\u0004 \u0005[להישאל\u0006\u0005]\u0006 על הנזירות השניה ואם כן יהיה מקום לנזירות הראשונה לחול בשלימותה — \u0003חיילא\u0004 \u0005[חלה\u0006\u0005]\u0006 הנזירות באותם עשרים יום, יש לשאול: \u0003אמר \"הריני נזיר שמשון\u0004 \u0003לאחר עשרים יום ומעכשיו\u0004 אני \u0003נזיר סתם\", מהו\u0004 הדין? \u0003הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 הרי \u0003לא אפשר לאיתשולי\u0004 \u0005[להישאל\u0006\u0005]\u0006 לנזירות שמשון, ונמצא שאין שום אפשרות להשלים את הנזירות הראשונה, ואם כן \u0003מי חיילא\u0004 \u0005[האם חלה\u0006\u0005]\u0006 הנזירות הראשונה, \u0003או לא?\u0004 ועוד שואלים: אם \u0003אמר\u0004 \u0003\"\u0004הריני \u0003כמשה בשבעה באדר\", מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 האם לומר שיש כאן לשון נזירות, שכשם שמשה נפטר ולא שתה עוד יין מאז, כך הוא מקבל על עצמו נזירות, או שמא אין כאן משמעות של נזירות?","ומעירים: \u0003פשוט מינייהו קדמייתא\u0004 \u0005[פתור מהן,\u0006 מכל השאלות הללו, לפחות את השאלה \u0005הראשונה]\u0006 שהובאה בראש הסוגיה, ששנינו במפורש בברייתא: \u0003\"הריני נזיר לאחר עשרים יום ומעכשיו מאה יום\" —\u0004 \u0003מונה עשרים\u0004 יום של נזירותו מעכשיו, \u0003ואחר כך מונה שלשים\u0004 יום של הנזירות שחלה אחר כך, \u0003ואחר כך מונה שמונים\u0004 יום \u0003כדי להשלים\u0004 את ימי ה\u0003נזירות\u0004 ה\u0003ראשונה.\u0004","וחוזרים לנושא שדובר עליו במשנה, כשנדר נזירות כשיהיה לו בן, ונזירות סתם, שצריך להתחיל נזירותו, ואם נולד לו בן בינתיים — מתחיל למנות ימי נזירות עבור בנו, ואחר כך משלים ימי נזירותו שלו. מבואר בתורה שנזיר שנטמא תוך נזירותו סותר את נזירותו לגמרי, וחוזר ומונה מתחילה נזירות חדשה. ויש לשאול: מה יקרה אם \u0003נטמא בימי\u0004 נזירותו על \u0003בנו,\u0004 כלומר, לאחר שהשלים כבר את נזירותו שלו? \u0003ר' יוחנן אמר: סותר\u0004 הכל, וצריך לחזור ולנהוג שתי נזירויות שלימות. \u0003ריש לקיש אמר: אינו סותר\u0004 אלא נזירות שניה (שנדר עבור בנו), אבל הימים שנהג נזירות עבור עצמו נחשבים לו.","ומסבירים את השיטות: \u0003ר' יוחנן אמר: סותר,\u0004 כי לדעתו \u0003חדא נזירות אריכתא\u0004 \u0005[נזירות אחת ארוכה\u0006\u0005]\u0006 \u0003היא, ריש לקיש אמר: אינו סותר,\u0004 כי \u0003נזירות דידיה\u0004 \u0005[שלו\u0006\u0005]\u0006 \u0003לחוד, ודבריה\u0004 \u0005[ושל בנו\u0006\u0005]\u0006 \u0003לחוד.\u0004"],["\u0003נטמא\u0004 למת \u0003בימי צרעתו,\u0004 שימי הצרעת עצמם אינם סותרים את ימי הנזירות להצריכו למנות מחדש נזירות שלימה, אבל גם אינם נמנים עמהם — \u0003ר' יוחנן אמר: סותר\u0004 את הימים הקודמים שנהג בהם נזירות קודם שנצטרע, ולאחר שיטהר מצרעתו עליו למנות מחדש נזירות שלימה שנדר. \u0003ריש לקיש אמר: אינו סותר,\u0004 ואין עליו אלא להשלים את ימי נזירותו לאחר שיטהר מצרעתו.","ומסבירים את השיטות, \u0003ר' יוחנן אמר: סותר, דהא\u0004 \u0005[שהרי\u0006\u0005]\u0006 \u0003בנזירות קאי\u0004 \u0005[\u0006הוא עומד, נמצא\u0005],\u0006 אף כשהוא מצורע, שכן צרעתו אינה סותרת את נזירותו. \u0003ריש לקיש אמר: אינו סותר\u0004 כי לדעתו \u0003צרעת לחוד ונזירות לחוד,\u0004 שהרי ימי הצרעת אינם נחשבים במנין ימי הנזירות.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריכה\u0006\u0005]\u0006 מחלוקת זו להיאמר בשני המקרים, \u0003דאי איתמר בהך קמייתא\u0004 \u0005[שאילו היה נאמר\u0006 רק בזו הראשונה\u0005],\u0006 שנטמא בימי הנזירות על הולדת בנו, היינו אומרים: דווקא \u0003בההיא אמר ר' יוחנן\u0004 ש\u0003סותר\u0004 גם את ימי נזירותו כי \u0003שם נזירות אחת היא,\u0004 אף כי מקורה בשני נדרים שונים. \u0003אבל בהא\u0004 \u0005[בזו\u0006\u0005]\u0006 בנצטרע ונטמא למת \u0003אימא\u0004 \u0005[אמור\u0006\u0005]\u0006 ש\u0003מודה ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003לריש לקיש\u0004 שאינו סותר את נזירותו, שכן \u0003נזיר לחוד וצרעת לחוד.\u0004","ומן הצד השני: \u0003ואי איתמר בהא\u0004 \u0005[ואילו היה נאמר\u0006 רק בזו\u0005],\u0006 בנטמא בימי צרעתו, היינו אומרים דווקא \u0003בהא קאמר\u0004 \u0005[בזו אמר\u0006\u0005]\u0006 \u0003ריש לקיש\u0004 שאינו סותר את נזירותו, \u0003אבל בהך\u0004 \u0005[בזו\u0006\u0005]\u0006 שנטמא בימי בנו \u0003אימא\u0004 \u0005[אמור\u0006\u0005]\u0006 ש\u0003מודה ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003לר' יוחנן\u0004 שסותר, שהרי שם נזירות אחד הוא, על כן \u0003צריכא\u0004 \u0005[צריך\u0006\u0005]\u0006 שתיאמר המחלוקת ביניהם בשני המקרים.","בעקבות מחלוקת ר' יוחנן וריש לקיש נדונה השאלה הבאה: \u0003נטמא ביום גידול שער,\u0004 כגון שנצטרע בימי נזירותו, ונטהר מצרעתו וגילח תגלחת המצורע, ואחר כך צריך להמתין עוד שלושים יום עד שיגדל שערו כדי שיוכל לגלח לנזירותו, ובמשך ימים אלה שנוספו על ימי נזירותו, בהם עליו להשלים גידול שערו — נטמא. \u0003רב אמר: אינו סותר\u0004 את הימים שמנה קודם לכן לנזירותו. ומסבירים: \u0003אפילו ל\u0004דעת \u0003ר' יוחנן דאמר\u0004 \u0005[שאומר\u0006\u0005]\u0006 שאם נטמא בימי נזירות בנו \u0003סותר\u0004 הכל — \u0003הני מילי היכא דקאי\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005היכן ש\u0006הוא \u0005עומד]\u0006 עדיין \u0003בנזירות,\u0004 אבל זמן \u0003גידול שער מישלם\u0004 \u0005[השלמת\u0006\u0005]\u0006 \u0003נזירות הוא\u0004 ואינו חלק מן הנזירות עצמה.","\u0003ושמואל אמר: סותר.\u0004 ומסבירים: ו\u0003אפילו ל\u0004דעת \u0003ריש לקיש דאמר\u0004 \u0005[שאומר\u0006\u0005]\u0006 שאם נטמא בימי נזירות בנו \u0003אין סותר\u0004 את ימי נזירותו — \u0003התם\u0004 \u0005[שם\u0006\u0005]\u0006 מדובר דווקא ב\u0003שתי נזירות\u0004 (נזירויות) שונות, שלו ושל בנו, אבל \u0003הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 \u0003חדא נזירותא\u0004 \u0005[נזירות אחת\u0006\u0005]\u0006 היא, שימי גידול השיער משלימים את נזירותו.","\u0003אמר רב חסדא: הכל מודים שאם קדש שער בדם,\u0004 שנזיר שהשלים ימי נזירותו והביא קרבנותיו, ונזרק הדם ועדיין לא גילח שערו, ונטמא — \u0003אין לו תקנה,\u0004 שאינו יכול להיות מותר בשתיית יין ובגילוח. שכן לא הותר על ידי הקרבנות שהקריב — מאחר שנטמא, וקרבן אחר להתירו אינו יכול להביא — שהרי כבר הביא קרבנות על נזירותו זו, ואין מביאים פעמיים קרבנות על נזירות אחת.","ושואלים: \u0003אליבא דמאן\u0004 \u0005[לפי שיטת מי\u0006\u0005]\u0006 אמר רב חסדא הלכה זו? \u0003אי אליבא\u0004 \u0005[אם לשיטת\u0006\u0005]\u0006 \u0003ר' אליעזר\u0004 — אין הלכה כן, שהרי \u0003כיון דאמר\u0004 \u0005[שאומר\u0006\u0005]\u0006 ר' אליעזר ש\u0003תגלחת מעכבת\u0004 השלמת נזירותו, ואם כן טומאה של \u0003תוך מלאת היא\u0004 בתוך זמן הנזירות, ומדוע אין לו תקנה? \u0003ולסתור\u0004 \u0005[ושיסתור\u0006\u0005]\u0006 ימי הנזירות וינהג נזירות נוספת במקומם, ואחר כך יגלח כדין! \u0003אלא\u0004 תאמר \u0003אליבא דרבנן\u0004 \u0005[לשיטת חכמים\u0006\u0005]\u0006 אמר רב חסדא הלכה זו — \u0003האמרי\u0004 \u0005[הרי אומרים\u0006 הם\u0005]\u0006 \u0003תגלחת לא מעכבת,\u0004 והרי זה כמי שנטמא לאחר ששלמה נזירותו! ומשיבים: \u0003לעולם\u0004 תאמר שהוא \u0003אליבא דרבנן\u0004 \u0005[לשיטת חכמים\u0006\u0005],\u0006 \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"אין לו תקנה\"\u0004 — הכוונה \u0003אין לו תקנה למצות גילוח\u0004 שאינו יכול לקיים מצוות גילוח בטהרה כדינה.","\u0003אמר ר' יוסי בר' חנינא: נזיר שכלו לו ימיו,\u0004 כלומר, ימי נזירותו, ועדיין לא הביא את קרבנותיו — אם נטמא למתים הרי זה \u0003לוקה על הטומאה\u0004 כדין כל נזיר שנטמא, אבל \u0003אינו לוקה על התגלחת\u0004 אם התגלח \u0003ולא על היין\u0004 אם שתה. ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה\u0006\u0005]\u0006 \u0003טומאה דלקי\u0004 \u0005[שלוקה\u0006 עליה\u0005]\u0006 — ש\u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 \u0003\"כל ימי הזירו לה'\u0004 על נפש מת לא יבוא\u0003\"\u0004 (במדבר ו, ו), ולמדו מריבוי הלשון \"כל\" \u0003לרבות\u0004 (להוסיף) \u0003ימים שלאחר מלאת\u0004 השלמת הנזירות, \u0003כימים שלפני מלאת\u0004 שאסור לו להיטמא בהם במת, ולוקה על כך.","אולם \u0003אי הכי\u0004 \u0005[אם כך\u0006\u0005]\u0006 על ה\u0003תגלחת נמי ליחייב\u0004 \u0005[גם כן שיתחייב\u0006\u0005]\u0006 מלקות, \u0003דהא אמר רחמנא\u0004 \u0005[שהרי אמרה תורה\u0006\u0005]\u0006 \u0003\"כל ימי נדר נזרו תער לא יעבר על ראשו\"\u0004 (במדבר ו, ה) וגם שם לשון \"כל\" באה לרבות, \u0003לעשות ימים שלאחר מלאת כימים שלפני מלאת! ותו\u0004 \u0005[ועוד\u0006\u0005],\u0006 גם לענין שתיית יין, הלוא נאמר \u0003\"כל ימי נזרו מכל אשר יעשה מגפן היין...\u0004 לא יאכל\u0003\"\u0004 (במדבר ו, ד), וריבוי זה של \"כל\" בא \u0003לעשות ימים שלאחר מלאת כימים שלפני מלאת\u0004 לענין איסור שתיית יין, ואם כן מה טעם ההבדל בדין בין טומאה ובין תגלחת ושתיית יין?"],["\u0003שאני הכא\u0004 \u0005[שונה כאן\u0006\u0005]\u0006 בענין טומאה \u0003דאמר רחמנא\u0004 \u0005[שאמרה תורה\u0006\u0005]:\u0006 \u0003\"וטמא ראש נזרו\"\u0004 (במדבר ו, ט), לומר, כל \u0003מי שנזרו\u0004 (שערו) \u0003תלוי לו בראשו\u0004 אף שכלו ימי נזירותו — הריהו חייב על הטומאה. \u0003מיתיבי\u0004 \u0005[מקשים\u0006\u0005]\u0006 על כך ממה ששנינו: \u0003נזיר שכלו לו ימיו\u0004 — \u0003אסור לגלח ולשתות יין ולטמא למתים, ואם גילח\u0004 או \u0003שתה יין ונטמא למתים —\u0004 \u0003הרי זה סופג\u0004 (לוקה) \u0003את הארבעים\u0004 מלקות שלוקה בהם העובר על \"לאו\" מן התורה. משמע שעל כולם לוקה, והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006\u0005]\u0006 לדברי ר' יוסי בר' חנינא, ונדחו דבריו.","אמר אדם: \u0003\"הריני נזיר לכשיהא לי בן\" ו\u0004חזר ואמר \u0003\"\u0004הריני \u0003נזיר\u0004 מעכשיו \u0003מאה יום\"\u0004 והתחיל למנות את מאה ימי נזירותו, אם \u0003נולד לו בן עד שבעים\u0004 יום מתחילת ימי נזירותו — \u0003לא הפסיד כלום,\u0004 שמניח את נדר נזירותו למאה הימים, ומונה שלושים ימים לנזירות עבור בנו, שכן קבלת נזירות בנו קדמה לקבלת נזירותו שלו, וחוזר ומשלים שלושים יום (או יותר) לנזירותו שלו. אבל אם נולד הבן \u0003לאחר שבעים\u0004 יום — \u0003סותר\u0004 את \u0003שבעים\u0004 הימים הראשונים, שצריך להתחיל את הנזירות עבור בנו, ולאחר שיגלח על נזירות בנו ינהג מאה ימי נזירותו. וטעם הדבר, שאינו יכול להשלים את מותר ימי נזירותו שלו לאחר שגילח על נזירות בנו, \u0003ש\u0004הרי \u0003אין תגלחת פחות משלשים יום.\u0004","\u0003אמר רב: יום שבעים\u0004 עצמו \u0003עולה\u0004 (נחשב) \u0003לכאן ולכאן,\u0004 הן לסוף שבעים יום של נזירותו שלו והן לתחילת נזירות בנו. ומקשים על כך, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003נולד לו עד שבעים —\u0004 \u0003לא הפסיד כלום,\u0004 ומשמע בכלל זה יום שבעים עצמו. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006\u0005]\u0006 לומר ש\u0003עולה לכאן ולכאן,\u0004 נמצא שלא זו בלבד שלא הפסיד בכך אלא הוא עוד \u0003איתגורי מיתגר\u0004 \u0005[מרויח\u0006\u0005]\u0006 יום אחד, ומה מקום לנקוט במשנה לשון \"לא הפסיד\"! ומשיבים: \u0003אלא בדין הוא,\u0004 מן הדין ראוי היה ש\u0003לא ליתני\u0004 \u0005[לשנות\u0006\u0005]\u0006 במשנה \u0003\"עד שבעים\u0004 לא הפסיד כלום \u0003\"\u0004, שהרי כאמור, אם מדובר ביום שבעים עצמו הוא אפילו מרויח מכך, \u0003ו\u0004אולם \u0003משום דקתני סיפא\u0004 \u0005[ששונה בסוף\u0006\u0005]\u0006 \u0003\"אחר שבעים סותר שבעים\"\u0004 ועניינו שהוא מפסיד משום כך, \u0003קתני רישא\u0004 \u0005[הריהו שונה בתחילת\u0006 המשנה\u0005]\u0006 בלשון ניגוד \"עד \u0003שבעים\u0004 לא הפסיד\".","ומקשים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 \u0003מסיפא\u0004 \u0005[מסופה\u0006\u0005]\u0006 של המשנה שלא כדעת רב: \u0003נולד אחר שבעים —\u0004 \u0003סותר שבעים,\u0004 ואם יום שבעים ואחד עולה לו, הרי נשארו לו עוד שלושים ימים שלמים, ולמה יסתור הראשונים? ודוחים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אחר\" —\u0004 \u0003אחר אחר,\u0004 כלומר, ביום השבעים ושניים, שהם יום אחר יום מיום השבעים.","ומקשים: ולדבריך, \u0003אבל אחר ממש\u0004 ביום השבעים ואחד \u0003מאי\u0004 \u0005[מה\u0006\u0005]\u0006 יהיה דינו — \u0003הכי נמי דלא סתר\u0004 \u0005[כך גם כן שאינו סותר\u0006\u0005]?\u0006 \u0003אי הכי מאי איריא דתני\u0004 \u0005[אם כך, מה שייך,\u0006 מדוע דווקא שונה\u0005]\u0006 \u0003נולד עד שבעים לא הפסיד כלום? אפילו\u0004 ביום של \u0003אחר שבעים נמי הא אמרת לא סתר\u0004 \u0005[גם כן, הרי אמרת שאינו סותר\u0006\u0005]!\u0006 \u0003אלא שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 ש\u0003\"אחר\"\u0004 פירושו אחר \u0003ממש,\u0004 כלומר, ביום שבעים ואחד. \u0003וכן מתניתין\u0004 \u0005[משנתנו\u0006\u0005]\u0006 קשה \u0003לרב, שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 שאין התנא של משנתנו סבור כרב.","ושואלים: אם כן, \u0003ורב כמאן\u0004 \u0005[כ\u0006דעת מי\u0005]\u0006 \u0003אמרה לשמעתיה\u0004 \u0005[את הלכתו\u0006 זו\u0005],\u0006 שאם אינה כדברי משנתנו, על איזה תנא סמך שאמר שמקצת היום נחשב ככולו? \u0003אילימא\u0004 \u0005[אם תאמר\u0006\u0005]\u0006 \u0003כ\u0004דעת \u0003אבא שאול, דתנן\u0004 \u0005[ש\u0006כן שנינו במשנה\u0005]\u0006 במסכת מועד קטן: \u0003הקובר את מתו שלשה ימים קודם לרגל —\u0004 \u0003בטלה ממנו גזירת שבעה\u0004 (כלומר, האיסורים והמנהגים של שבעת ימי האבל הראשונים) שכיון שהתאבל שלושה ימים קודם הרגל, הרי הרגל מבטל ממנו את אבילות שאר השבעה.","אם קבר את מתו \u0003שמנה ימים קודם לרגל —\u0004 \u0003בטלה ממנו\u0004 גם \u0003גזירת שלשים\u0004 (דיני אבילות שנוהג שלושים יום אחר המוות) שהרי כבר נהג יום אחד באבילות שלושים, ושוב אינו צריך להשלים. \u0003ומותר לספר\u0004 את שערו \u0003ערב הרגל\u0004 משום כבוד הרגל, \u0003ואם לא סיפר ערב הרגל —\u0004 \u0003אסור לספר\u0004 את השיער \u0003אחר הרגל\u0004 עד שיימלאו שלושים יום לאבילות."],["\u0003אבא שאול אומר: אפילו לא סיפר\u0004 שערו \u0003קודם הרגל —\u0004 \u0003מותר לספר אחר הרגל,\u0004 וטעמו: \u0003שכשם שמצות שלשה\u0004 שאם נהג שלושה ימים של אבילות לפני החג \u0003מבטלת\u0004 את \u0003גזירת שבעה\u0004 ואינו צריך להשלים לשבעה ימי אבילות לאחר הרגל — \u0003כך מצות שבעה\u0004 שנהג אבילות ביום השביעי \u0003מבטלת גזירת שלשים.\u0004","ומציעים: \u0003מאי טעמא\u0004 \u0005[מה הטעם\u0006\u0005]\u0006 של \u0003אבא שאול? —\u0004 \u0003לאו\u0004 \u0005[האם לא\u0006\u0005]\u0006 \u0003משום דקסבר\u0004 \u0005[ש\u0006הוא סבור\u0005]\u0006 שיום \u0003שביעי עולה לכאן ולכאן,\u0004 שנחשב כסוף שבעה, והתחלת שלושים וכדברי רב? ודוחים: אין זו ראיה לשיטתו, שכן \u0003דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר\u0006\u0005]\u0006 \u0003אבא שאול\u0004 שניתן להחשיב יום לכאן ולכאן \u0003אלא באבילות שבעה\u0004 שחיובה הוא \u0003דרבנן\u0004 \u0005[מ\u0006דברי סופרים\u0005],\u0006 \u0003אבל בנזיר\u0004 שחיובו \u0003דאורייתא\u0004 \u0005[מן התורה\u0006\u0005] —\u0006 \u0003לא!\u0004","\u0003אלא רב\u0004 ש\u0003אמר —\u0004 \u0003כ\u0004שיטת \u0003ר' יוסי\u0004 אמר, \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 \u0003ר' יוסי אומר: שומרת יום כנגד יום,\u0004 אשה שראתה דם יום אחד (או שניים) בימי זיבתה (שלא בזמן נידתה), ושומרת עצמה בטהרה יום שלאחר מכן, ואם לא תראה דם טובלת וטהורה, \u0003ששחטו וזרקו עליה\u0004 (עבורה) דם קרבן פסח \u0003ב\u0004יום \u0003שני שלה\u0004 (יום ששמרה כטהרה)","\u0003ואחר כך ראתה\u0004 דם — \u0003הרי זו אינה אוכלת\u0004 את קרבן הפסח, שטמאה היא, \u0003ו\u0004אולם \u0003פטורה\u0004 היא \u0003מלעשות פסח שני\u0004 (כדין מי שלא הקריב פסח ראשון), כיון שבזמן ששחטו את קרבן הפסח עליה טהורה היתה, אף שלאחר מכן נטמאה ולא היתה יכולה לאכול בפסח, מכל מקום קיימה את מצוות ההקרבה.","ונברר: \u0003מאי טעמא\u0004 \u0005[מה הטעם\u0006\u0005]\u0006 של \u0003ר' יוסי, לאו\u0004 \u0005[האם לא\u0006\u0005]\u0006 \u0003משום דקסבר\u0004 \u0005[ש\u0006הוא סבור\u0005]\u0006 ש\u0003מקצת היום ככולו?\u0004 שאותו חלק מן היום שהיתה טהורה בו נחשב כיום שלם, וכאילו היתה טהורה כל היום. ודוחים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 יודע אתה שזה טעמו? ודוחים: אין מכאן ראיה לשיטת רב, שכן \u0003ודלמא\u0004 \u0005[ושמא\u0006\u0005]\u0006 \u0003משום דקסבר\u0004 \u0005[ש\u0006ר' יוסי סבור\u0005]\u0006 \u0003מכאן ולהבא הוא מטמא,\u0004 שכך הוא דין הזבה: שטומאתה ביום השני אינה מתחילה אלא מזמן שראתה דם, וקודם לכן אינה טמאה, ולכן באותו זמן ששחטו את הקרבן טהורה היתה.","על כך מקשים: \u0003ומי סבר\u0004 \u0005[והאם סבור\u0006\u0005]\u0006 \u0003ר' יוסי הכי\u0004 \u0005[כך\u0006\u0005],\u0006 שסיבת הדבר שפטורה מפסח שני הריהי משום שרק מכאן ולהבא היא מטמאת?","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא אחרת\u0005],\u0006 \u0003ר' יוסי אומר: זב בעל שתי ראיות,\u0004 שלאחר שתי ראיות הוא מטמא, וצריך להמתין שבעה ימים נקיים עד שיטהר, \u0003ששחטו וזרקו עליו\u0004 (עבורו) דם קרבן הפסח \u0003ב\u0004יום ה\u0003שביעי\u0004 לימים הנקיים, \u0003וכן שומרת יום כנגד יום ששחטו וזרקו עליה\u0004 (עבורה) את קרבן הפסח, \u0003ואחר כך ראו\u0004 הזב — זוב, והאשה — דם נידה, \u0003אף על פי שמטמאין משכב ומושב למפרע —\u0004 \u0003פטורין מלעשות פסח שני.\u0004 הרי מפורש לדעת ר' יוסי שטומאה זו חלה למפרע, ולא מכאן ולהבא. ואם כן מוכרחים לומר שהטעם שפוטרם מקרבן פסח שני הוא מפני שמקצת היום ככולו, וחלק היום לפני שנטמאו, בו זרקו עליהם כהלכה את הדם, נחשב להם כיום שלם.","ודוחים: \u0003מאי\u0004 \u0005[מה\u0006\u0005]\u0006 שאמר ר' יוסי בברייתא שמטמאים \u0003למפרע\u0004 — הוא רק \u0003מדרבנן\u0004 \u0005[מדברי חכמים\u0006\u0005],\u0006 ואולם לדעתו מדין תורה טומאתם היא רק מזמן הראיה ולהבא. ומעירים: \u0003הכי נמי מיסתברא\u0004 \u0005[כך גם כן מסתבר\u0006\u0005]\u0006 לומר כדעת ר' יוסי, ומדוע, \u0003דאי סלקא דעתך מדאורייתא\u0004 \u0005[שאם עולה על דעתך\u0006 לומר שטמאים למפרע מדין תורה\u0005]\u0006 \u0003אמאי\u0004 \u0005[מדוע\u0006\u0005]\u0006 \u0003פטורין מלעשות פסח שני?\u0004 הלא טמאים היו!","ומשיבים: אין מכאן ראיה, כי \u0003לעולם אימא\u0004 \u0005[אומר\u0006\u0005]\u0006 \u0003לך\u0004 ש\u0003טומאה\u0004 זו למפרע \u0003דאורייתא\u0004 \u0005[מן התורה\u0006\u0005]\u0006 היא, אלא אפשר להסביר באופן אחר: טומאת \u0003תהום\u0004 של \u0003זיבה התירו.\u0004 שכן למדנו שבפסח הותרה טומאה בלתי ידועה (\"טומאת תהום\") של מת — שאם הביא אדם קרבן ולאחר מכן נודע שנטמא במת, בטומאה שלא היתה ידועה לאיש (כמו התהום, המכוסה מעין כל) אינו צריך להביא שוב קרבן פסח. ואפשר לומר שר' יוסי סבור שהוא הדין גם לטומאת זיבה, שכיון שבשעת ההקרבה היה המקריב טהור ואי אפשר היה לדעת שתבוא שוב זיבה ותטמאנו — הרי גם זה בגדר טומאת התהום, ולכן יצאו ידי חובתם.","ומעירים: \u0003ואף ר' אושעיא סבר\u0004 שלדעת ר' יוסי טומאת זוב \u0003למפרע מדרבנן\u0004 \u0005[מדברי סופרים\u0006\u0005]\u0006 היא, \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 \u0003ר' אושעיא אמר: (אבל) הרואה זב\u0004 (זיבה) \u0003בשביעי שלו,\u0004 ביום השביעי משבעת הימים הנקיים שמנה — \u0003סותר את\u0004 שבעת הימים הנקיים \u0003ש\u0004מנה \u0003לפניו\u0004 וצריך למנות שוב שבעה נקיים. \u0003ואמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003ר' יוחנן: לא נסתור\u0004 \u0005[יסתור\u0006\u0005]\u0006 \u0003אלא יומו,\u0004 שאינו צריך למנות אלא יום נקי אחד נוסף.","על דברי ר' יוחנן תוהים: \u0003מה נפשך\u0004 \u0005[מה רצונך,\u0006 דעתך, לומר\u0005]\u0006 בענין זה? \u0003אי סתר\u0004 \u0005[אם\u0006 הוא סותר\u0005]\u0006 על ידי ראיה זו, כדין זב שרואה ראיה בתוך שבעה נקיים, אם כן צריך להיות ש\u0003כולהו סתר\u0004 \u0005[את\u0006 כל הימים כולם סותר\u0005],\u0006 ולא יום זה בלבד. \u0003אי לא סתר\u0004 \u0005[אם אינו סותר\u0006\u0005]\u0006 שאין זה נחשב כראיית זוב בתוך שבעה נקיים, אלא כראיה ראשונה של זיבה חדשה — \u0003לא נסתור\u0004 \u0005[יסתור\u0006\u0005]\u0006 כלל \u0003ו\u0004גם \u0003לא\u0004 את \u0003יומו!\u0004 ומה טעם לדברי ר' יוחנן שיסתור רק יום אחד? \u0003אלא אימא\u0004 \u0005[אמור\u0006\u0005],\u0006 תקן את דברי ר' יוחנן, שכך אמר: \u0003לא נסתור\u0004 \u0005[יסתור\u0006\u0005]\u0006 כלל \u0003ו\u0004אף \u0003לא\u0004 את \u0003יומו,\u0004 שתיחשב לו ראיה זו כראיה ראשונה של זוב אחר."],["\u0003ואמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 ר' אושעיא: \u0003ר' יוסי קאי כותיך\u0004 \u0005[עומד בשיטתך\u0006\u0005]\u0006 \u0003דאמר\u0004 \u0005[שאומר\u0006\u0005]\u0006 גם הוא \u0003מכאן ולהבא מטמא,\u0004 ולכן אין טומאה לאחר תחילת יום השביעי סותרת. ולכאורה קשה על ר' אושעיא: \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003ר' יוסי למפרע הוא דאמר\u0004 \u0005[שאומר\u0006\u0005]\u0006 כמו שהבאנו קודם! אלא ודאי יש לפרש שר' אושעיא סבור: \u0003מאי\u0004 \u0005[מה\u0006\u0005]\u0006 \u0003למפרע\u0004 שאמר ר' יוסי — כוונתו רק \u0003מדרבנן\u0004 \u0005[מדברי סופרים\u0006\u0005]\u0006 ולא מן התורה. על עצם שיטתו של ר' יוסי שואלים: \u0003ור' יוסי, מכדי סבר\u0004 \u0005[הרי סבור\u0006\u0005]\u0006 הוא \u0003מקצת היום ככולו,\u0004 אם כן \u0003זבה גמורה דמייתא\u0004 \u0005[שמביאה\u0006\u0005]\u0006 \u0003קרבן היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה\u0006\u0005]?\u0006 שהרי \u0003כיון דחזיא בפלגיה דיומא\u0004 \u0005[שהיא רואה\u0006 דם בחצי היום\u0005],\u0006 אם מקצת היום ככולו, אם כן \u0003אידך פלגיה דיומא סליק\u0004 \u0005[חצי היום האחר הולך\u0006\u0005]\u0006 \u0003לה לשימור,\u0004 שהרי בכל פעם אנחנו רואים את מקצת היום ככולו! ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור\u0006\u0005]\u0006 \u0003דקא שפעה\u0004 \u0005[ש\u0006היא שופעת דם\u0005]\u0006 בלי הפסק \u0003תלתא תלתא יומי בהדי הדדי\u0004 \u0005[שלושה ימים יחד,\u0006 רצופים\u0005].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור\u0006\u0005]:\u0006 \u0003דחזיא תלתא יומי\u0004 \u0005[שרואה\u0006 דם שלושה ימים\u0005]\u0006 \u0003סמוך לשקיעת החמה\u0004 ונמצא שנטמאת בכל יום בסוף היום ובראשית היום הבא ש\u0003לא הואי\u0004 \u0005[היתה\u0006\u0005]\u0006 לה \u0003שהות\u0004 ביום הבא להיטהר \u0003דסליק ליה למניינא\u0004 \u0005[שתעלה לה למנין\u0006\u0005]\u0006 של יום טהרה כנגד יום הטומאה.","","","\u0003מי שאמר \"הריני נזיר\"\u0004 סתם, ולא פירש כמה ימים יהיה נזיר — \u0003מגלח\u0004 את שערו ב\u0003יום שלשים ואחד\u0004 לתחילת הנזירות, \u0003ואם גילח ליום שלשים —\u0004 \u0003יצא.\u0004 אם אמר במפורש \u0003\"הריני נזיר שלשים יום\" —\u0004 \u0003אם גילח ליום שלשים לא יצא,\u0004 אלא חייב להשלים שלושים יום בנזירות ולגלח ביום שלושים ואחד.","\u0003מי שנזר שתי נזירות\u0004 שקיבל על עצמו בנדר לנהוג שתי נזירויות — \u0003מגלח את\u0004 שערו על הנזירות \u0003הראשונה\u0004 ב\u0003יום שלשים ואחד, ואת השניה\u0004 ב\u0003יום ששים ואחד\u0004 שכיון שנזירותו החלה כבר ביום השלושים ואחד לאחר שגילח, נמצא מגלח לאחר שלושים יום. \u0003ואם גילח את הראשונה\u0004 ב\u0003יום שלשים —\u0004 \u0003מגלח את השניה\u0004 ב\u0003יום ששים\u0004 (שהוא יום שלושים ואחד לתחילת הנזירות השניה), \u0003ואם גילח\u0004 את השניה ב\u0003יום ששים חסר אחד\u0004 — גם הוא \u0003יצא,\u0004 שהרי בדיעבד אם גילח ביום שלושים לנזירות — יצא.","\u0003וזו עדות העיד ר' פפייס,\u0004 שקיבל מרבותיו \u0003על מי שנזר שתי נזירות, שאם גילח את הראשונה\u0004 ב\u0003יום שלשים מגלח את השניה ליום ששים, ואם גילח\u0004 את השניה \u0003ליום ששים חסר אחד יצא,\u0004 משום \u0003שיום של שלשים\u0004 של מנין ראשון \u0003עולה לו מן המנין\u0004 לנזירות השניה.","\u0003מי שאמר \"הריני נזיר\"\u0004 סתם, אם \u0003נטמא\u0004 ב\u0003יום שלשים —\u0004 \u0003סותר את הכל,\u0004 וצריך לחזור ולנהוג נזירות שלימה מתחילה. \u0003ר' אליעזר אומר: אינו סותר אלא שבעה\u0004 ימים, וצריך למנות שבעה ימים אחרים עד שיטהר, ויביא קרבנותיו לאחר מכן. אמר \u0003\"הריני נזיר שלשים יום\",\u0004 שבמקרה כזה אם גילח ביום שלושים לא יצא כמבואר לעיל, אם \u0003נטמא יום שלשים\u0004 לכל הדעות \u0003סותר את הכל.\u0004 אמר \u0003\"הריני נזיר מאה יום\",\u0004 אם \u0003נטמא\u0004 ב\u0003יום מאה —\u0004 \u0003סותר את הכל. ר' אליעזר אומר: אינו סותר אלא שלשים\u0004 יום, שצריך לחזור ולמנות שלושים יום בלבד. אם \u0003נטמא\u0004 ב\u0003יום מאה ואחד\u0004 אבל עדיין לא הביא את קרבנותיו — \u0003סותר\u0004 רק \u0003שלשים יום\u0004 ולא את כל זמן נזירותו. \u0003ר' אליעזר אומר: אינו סותר אלא שבעה.\u0004 שנינו במשנה: \u0003מי שאמר \"הריני נזיר\" ונטמא\u0004 ב\u0003יום\u0004 ה\u0003שלשים —\u0004 \u0003סותר את הכל, ר' אליעזר אומר: אינו סותר אלא שבעה.\u0004",""],["\u0003קסבר\u0004 \u0005[סבור\u0006\u0005]\u0006 \u0003ר' אליעזר: כל\u0004 שנטמא \u0003אחר מלאת\u0004 ימי נזירותו רק \u0003שבעה\u0004 ימים \u0003סותר,\u0004 ולדעתו יום שלושים אחר מלאת הוא. עוד שנינו במשנה שאם אמר \u0003\"הריני נזיר שלשים יום\" ונטמא\u0004 ב\u0003יום שלשים —\u0004 \u0003סותר את הכל,\u0004 על כך \u0003לא פליג\u0004 \u0005[חלק\u0006\u0005]\u0006 \u0003ר' אליעזר,\u0004 כי מדובר כאן כאשר \u0003אמר\u0004 במפורש שמקבל עליו נזירות שלושים יום \u0003שלימין,\u0004 ובמקרה זה נחשב הדבר שנטמא בתוך הנזירות.","עוד שנינו שאם אמר \u0003\"הריני נזיר מאה יום\" ונטמא\u0004 ב\u0003יום מאה —\u0004 \u0003סותר את הכל, ר' אליעזר אומר: אינו סותר אלא שלשים. ו\u0004את המשנה \u0003כולה\u0004 יש להמשיך ולפרש \u0003כדהוינן\u0004 \u0005[כפי שעסקנו\u0006\u0005]\u0006 \u0003בה אליבא\u0004 \u0005[על פי שיטתם\u0006\u0005]\u0006 של \u0003בר פדא ורב מתנא\u0004 בפרק ראשון בדפים ה-ו.","\u0003מי שנזר\u0004 נדר נזירות \u0003והוא\u0004 נמצא אז \u0003בבית הקברות, אפילו היה שם שלשים יום\u0004 שלמים ולא יצא — \u0003אין\u0004 ימים אלה שהיה בבית הקברות \u0003עולין\u0004 (נחשבים) \u0003לו מן המנין\u0004 של הנזירות, \u0003ו\u0004לפיכך \u0003אינו מביא קרבן טומאה,\u0004 לפי שנדר הנזירות לא חל עליו עדיין. אם \u0003יצא\u0004 מבית הקברות \u0003ונכנס\u0004 אליו שנית — \u0003עולין לו\u0004 הימים הללו \u0003מן המנין,\u0004 כלומר, שחלה עליו הנזירות, \u0003ו\u0004לפיכך \u0003מביא\u0004 \u0003קרבן טומאה\u0004 לאחר שנכנס שוב.","\u0003ר' אליעזר אומר: לא\u0004 נאמרה הלכה זו אם נכנס לבית הקברות \u0003בו ביום\u0004 שיצא משם, \u0003שנאמר\u0004 בקשר להלכות הנזיר שנטמא: \u0003\"והימים הראשנים יפלו\"\u0004 (במדבר ו, יב), ולמדים אנו מלשון זו: \u0003עד שיהו לו ימים ראשונים\u0004 של טהרה שנהג בהם נזירות, אבל אם לא היו ימים ראשונים של טהרה לא חלים עליו דינים אלה.","\u0003איתמר\u0004 \u0005[נאמר\u0006\u0005]\u0006 שנחלקו בענין \u0003מי שנזר והוא\u0004 נמצא אותה שעה \u0003בבית הקברות, ר' יוחנן אמר: נזירות חלה עליו, וריש לקיש אמר: אין נזירות חלה עליו.\u0004 ומסבירים את השיטות, \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 ש\u0003נזירות חלה עליו, סבר\u0004 \u0005[סבור\u0006\u0005]:\u0006 משעה שקיבל על עצמו נזירות \u0003מיתלא תליא וקיימא\u0004 \u0005[תלויה\u0006 היא ועומדת\u0005],\u0006 \u0003כיון דמשכחא\u0004 \u0005[שהיא מוצאת\u0006\u0005]\u0006 מצב שבו האדם נמצא ב\u0003טהרה\u0004 (אם יצא מבית הקברות), הריהי \u0003חיילא\u0004 \u0005[חלה\u0006\u0005]\u0006 עליו מיד. שבעצם הנדר חל עליו משעה שנדר, אלא שאין לו אפשרות לחול בפועל בהיותו במקום טמא. \u0003וריש לקיש אמר: אין נזירות חלה עליו\u0004 כל עיקר. ומשום כך \u0003אי הדר ואמר\u0004 \u0005[אם\u0006 הוא חוזר ואומר\u0005]\u0006 לאחר שיצא משם שהוא מקבל על עצמו נזירות — \u0003חיילא עליה\u0004 \u0005[חלה עליו\u0006\u0005],\u0006 \u0003ואי\u0004 \u0005[ואם\u0006\u0005]\u0006 \u0003לא\u0004 חוזר ואומר — \u0003לא\u0004 חלה עליו.","\u0003איתיביה\u0004 \u0005[הקשה לו\u0006\u0005]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממשנתנו: \u0003מי שנזר והוא בבית הקברות, אפילו היה שם שלשים יום —\u0004 \u0003אין עולין\u0004 לו \u0003מן המנין, ואינו מביא קרבן טומאה.\u0004 ונדייק: \u0003קרבן טומאה הוא\u0004 ש\u0003לא מייתי\u0004 \u0005[מביא\u0006\u0005],\u0006 \u0003הא מיחל\u0004 \u0005[הרי לחול\u0006\u0005] —\u0006 \u0003חיילא עליה\u0004 \u0005[חלה עליו\u0006\u0005]!\u0006 \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 הכוונה היא: \u0003אינו בתורת טומאה, ו\u0004משום כך \u0003אינו בתורת קרבן,\u0004 שאינו נזיר כלל.","ועוד \u0003איתיביה\u0004 \u0005[הקשה לו\u0006\u0005]\u0006 ר' יוחנן לריש לקיש, ממה ששנינו בברייתא: \u0003מי שהיה טמא ונזר,\u0004 שקיבל עליו נזירות בעודו טמא, מכל מקום הרי זה נוהג כנזיר בדיניו, ש\u0003אסור לגלח ולשתות יין וליטמא למתים. ואם גילח, ו\u0004כן אם \u0003שתה יין, ו\u0004כן אם \u0003נטמא למתים —\u0004 \u0003הרי זה סופג\u0004 (לוקה) \u0003את הארבעים,\u0004 מלקות שלוקה בהם העובר על איסור לא תעשה מן התורה. ומעתה נברר: \u0003אי אמרת בשלמא חיילא\u0004 \u0005[נניח אם אתה אומר\u0006 שהנזירות חלה\u0005]\u0006 עליו באותה שעה — \u0003היינו טעמא\u0004 \u0005[זה הטעם\u0006\u0005]\u0006 ש\u0003סופג את הארבעים\u0004 ככל העובר על נזירותו, \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה\u0006\u0005]\u0006 שהנזירות מעיקרה \u0003לא חיילא\u0004 \u0005[חלה\u0006\u0005],\u0006 \u0003אמאי\u0004 \u0005[מדוע\u0006\u0005]\u0006 \u0003סופג את הארבעים?\u0004"],["\u0003הכא במאי עסקינן\u0004 \u0005[כאן\u0006 בברייתא זו במה אנו עוסקים\u0005] —\u0006 \u0003ביוצא ונכנס,\u0004 שיצא ממקום הטומאה ונטהר כדין, וקיבל עליו שוב נזירות, וחלה עליו נזירות, ואחר כך חזר ונכנס למקום טמא.","\u0003איתיביה\u0004 \u0005[הקשה לו\u0006\u0005]\u0006 עוד ר' יוחנן לריש לקיש ממה ששנינו: \u0003אין בין טמא שנזר לנזיר טהור שנטמא אלא\u0004 דבר זה בלבד: \u0003טמא שנזר\u0004 — יום \u0003שביעי שלו\u0004 שנטהר בו מטומאתו \u0003עולה\u0004 (נחשב) \u0003לו למנין\u0004 הימים, שמיד כשנטהר מתחיל למנות את ימי נזירותו, \u0003ו\u0004אילו \u0003נזיר טהור שנטמא —\u0004 \u0003אין\u0004 יום \u0003שביעי שלו עולה לו למנין,\u0004 אלא מתחיל למנות את ימי נזירותו מיום הבאת קרבנותיו, שהוא למחרת, ביום השמיני. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006\u0005]\u0006 לומר ש\u0003לא חיילא\u0004 \u0005[חלה\u0006\u0005]\u0006 הנזירות על הטמא עד שידור שוב, \u0003אמאי\u0004 \u0005[מדוע\u0006\u0005]\u0006 אומרת הברייתא כי \u0003עולה לו\u0004 היום השביעי \u0003מן המנין,\u0004 ומשמע — מאליו, כטהור שנטמא?","\u0003אמר מר בר רב אשי:\u0004 לא כך היתה המחלוקת בין ר' יוחנן לריש לקיש, ולענין \u0003מיחל\u0004 \u0005[חלות\u0006\u0005]\u0006 הנזירות — \u0003כולי עלמא לא פליגי דחיילא\u0004 \u0005[הכל אינם חלוקים ש\u0006היא חלה\u0005]\u0006 משעה שקיבל עליו בבית הקברות, \u0003אלא כי פליגי\u0004 \u0005[כאשר נחלקו\u0006\u0005]\u0006 היה זה \u0003למלקי\u0004 \u0005[ל\u0006ענין ללקות\u0005].\u0006 ובזאת נחלקו: \u0003ר' יוחנן סבר\u0004 \u0005[סבור\u0006\u0005]:\u0006 \u0003כיון דחיילא\u0004 \u0005[שחלה\u0006\u0005]\u0006 הנזירות — \u0003לקי\u0004 \u0005[לוקה\u0006\u0005]\u0006 על הטומאה. \u0003וריש לקיש סבר\u0004 \u0005[סבור\u0006\u0005]:\u0006 \u0003לא לקי\u0004 \u0005[אינו לוקה\u0006\u0005]\u0006 על הטומאה, \u0003ו\u0004אולם \u0003חיילא\u0004 \u0005[וחלה\u0006\u0005]\u0006 הנזירות לעניינים אחרים.","ואף על הסבר זה של מחלוקת \u0003איתיביה\u0004 \u0005[הקשה לו\u0006\u0005]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממשנתנו: \u0003מי שנזר והוא בבית הקברות, אפילו היה שם שלשים יום —\u0004 \u0003אין עולין לו\u0004 הימים ששהה שם \u0003מן המנין, ואינו מביא קרבן טומאה.\u0004 ונדייק: \u0003קרבן טומאה הוא\u0004 ש\u0003לא מייתי\u0004 \u0005[מביא\u0006\u0005],\u0006 ומכלל הדברים אתה מדייק: \u0003הא מילקי, לקי\u0004 \u0005[הרי\u0006 לענין ללקות, הוא לוקה\u0005]\u0006 \u0003עליה\u0004 ושלא כדעת ריש לקיש!","ומשיבים: אל תדייק כן, משום ש\u0003בדין הוא דליתני\u0004 \u0005[שישנה\u0006\u0005]\u0006 גם \u0003\"אינו לוקה\", אלא משום דקא בעי למיתנא סיפא\u0004 \u0005[שרוצה לשנות\u0006 בסוף\u0005]\u0006 בדין שאחר כך \u0003\"יצא ונכנס —\u0004 \u0003עולה לו מן המנין,\u0004 \u0003ומביא קרבן טומאה\"\u0004 — על כן \u0003תנא רישא\u0004 \u0005[שנה\u0006 גם בתחילה\u0005]\u0006 באותו סגנון \u0003\"אינו מביא קרבן טומאה\",\u0004 ולא מיצה בתחילת המשנה את כל הבדלי ההלכה. ואין להקשות ממנה על ריש לקיש.","ומציעים עוד ראיה לשיטת ר' יוחנן, \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 ממה ששנינו: \u0003אין בין טמא שנזר לנזיר טהור שנטמא, אלא שטמא שנזר —\u0004 יום \u0003שביעי שלו,\u0004 לטומאתו, \u0003עולה לו מן המנין, ונזיר טהור שנטמא —\u0004 \u0003אין שביעי שלו עולה לו מן המנין.\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003למלקות —\u0004 \u0003זה וזה שוין! אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 ריש לקיש לר' יוחנן: \u0003לא\u0004 כך יש לדייק, אלא יש לדייק מכאן כי \u0003ל\u0004ענין \u0003תגלחת\u0004 ביום השביעי לטהרתם \u0003זה וזה שוין,\u0004 שאף טמא שנזר צריך לגלח.","ושואלים: אם כן, לדברי ריש לקיש \u0003אבל לענין מלקות מאי\u0004 \u0005[מה\u0006\u0005]\u0006 יהיה הדין — \u0003זה\u0004 (טהור שנטמא) \u0003לוקה, וזה\u0004 (טמא שנזר) \u0003אינו לוקה? ליתנייה\u0004 \u0005[שישנה אותו\u0006\u0005]\u0006 את ההבדל הזה גם כן, ומדוע שנו בברייתא רק הבדל אחד ביניהם? ומשיבים: \u0003בתקנתיה קא מיירי, בקלקוליה לא קא מיירי\u0004 \u0005[בתקנתו עוסקת\u0006 הברייתא הזו, בקלקולו אינה עוסקת\u0005]\u0006 ולכן אינה דנה בעונשיו, אלא באופן שבו הוא צריך לעשות את הדברים כראוי.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 ממה ששנינו בברייתא: \u0003מי שהיה טמא ונזר —\u0004 \u0003אסור לגלח ולשתות יין, ואם גילח,\u0004 או \u0003שתה יין,\u0004 או \u0003נטמא למתים —\u0004 \u0003הרי זה סופג\u0004 (לוקה) \u0003את הארבעים\u0004 מלקות שלוקה בהם העובר על \"לאו\" מן התורה! ומסכמים, הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006\u0005]\u0006 לריש לקיש ונדחו דבריו.","על סמך מסקנה זו, כר' יוחנן, שמי שנזר בהיותו בבית הקברות, לוקה על הטומאה אם התרו בו, \u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003רבא:\u0004 מי שנדר נדר \u0003נזיר והוא בבית הקברות, מהו\u0004 דינו? והשאלה היא: האם \u0003בעי\u0004 \u0005[צריך\u0006\u0005]\u0006 \u0003שהייה\u0004 (משך זמן מסויים שישהה בבית הקברות) על מנת \u0003ל\u0004התחייב על כך \u0003מלקות,\u0004 כמו מי שנטמא במקדש, שאינו לוקה משום כך אלא אם כן שהה שם, \u0003או לא?\u0004","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר\u0006\u0005]?\u0006 \u0003אילימא דאמרי ליה\u0004 \u0005[אם תאמר שאמרו לו\u0006\u0005]\u0006 בהתראה \u0003\"לא תינזור\",\u0004 אל תקבל על עצמך כאן את נדר הנזירות, ועבר וקיבל על עצמו, אם כן \u0003למה לי שהייה? נזיר\u0004 שנכנס לבית הקברות \u0003מאי טעמא לא בעי\u0004 \u0005[מה טעם אינו צריך\u0006\u0005]\u0006 \u0003שהייה\u0004 על מנת ללקות, אלא לוקה על עצם הכניסה — משום \u0003דקא מתרי ביה\u0004 \u0005[שמתרים בו\u0006\u0005]\u0006 שלא יכנס, ואם נכנס הרי הוא עושה מעשה עבירה, ולוקה. \u0003הכי נמי קא מתרי ביה\u0004 \u0005[כאן גם כן מתרים בו\u0006\u0005]\u0006 שלא ינזור, ואם נזר — ילקה מיד!"],["\u0003אלא\u0004 כך יש להסביר את שאלת רבא: \u0003כגון שנכנס\u0004 הנזיר לבית הקברות \u0003בשידה תיבה ומגדל\u0004 (ארון) שהם כלי עץ גדולים מאד שאינם מקבלים טומאה, ואם אדם נמצא בתוכם והם נמצאים בבית הקברות — אינו נטמא, \u0003ובא חבירו ופרע\u0004 (גילה) \u0003מעליו\u0004 את ה\u0003מעזיבה\u0004 (הגג) של הכלים הללו, ואז הוא נטמא בטומאת המת, והתרו בו שיצא.","והשאלה היא: \u0003כי גמירין\u0004 \u0005[כאשר למודים אנו\u0006 במסורת\u0005]\u0006 דין זה של חיוב מלקות על \u0003שהייה\u0004 בטומאה, הרי זה רק \u0003בבית המקדש, אבל אבראי\u0004 \u0005[בחוץ\u0006\u0005],\u0006 שלא במקדש, כגון נזיר בבית הקברות — \u0003לא,\u0004 וחייב מלקות אף אם לא שהה בבית הקברות. \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה\u0006\u0005]?\u0006 ואף נזיר בבית הקברות אינו לוקה אם לא שהה שם שהות מסויימת. לשאלה זו לא נמצאה תשובה ולכן \u0003תיקו\u0004 \u0005[תעמוד\u0006\u0005]\u0006 במקומה.","\u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003רב אשי:\u0004 מי ש\u0003נזר והוא\u0004 באותה שעה היה \u0003בבית הקברות,\u0004 מה דינו? האם \u0003טעון\u0004 (חייב) \u0003גילוח\u0004 לפני שינהג נזירות טהרה, \u0003או לא?\u0004 וצדדי השאלה: \u0003כי בעי\u0004 \u0005[כאשר\u0006 זה שנזיר טמא צריך\u0005]\u0006 \u0003תגלחת\u0004 הרי זה דווקא ב\u0003טהור שנטמא, דקא\u0004 \u0005[שהוא\u0006\u0005]\u0006 \u0003מטמא לנזירותיה\u0004 \u0005[את נזירותו\u0006\u0005],\u0006 \u0003אבל טמא שנזר,\u0004 שעדין לא חלה עליו נזירות טהרה — \u0003לא. או דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003לא שנא\u0004 \u0005[שונה\u0006\u0005]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 תשובה לשאלה, ממה ששנינו: \u0003מי שנזר והוא בבית הקברות, אפילו היה שם שלשים יום —\u0004 \u0003אינו עולה לו מן המנין, ואינו מביא קרבן טומאה.\u0004 ונדייק מכאן: \u0003קרבן טומאה הוא\u0004 ש\u0003לא מייתי\u0004 \u0005[מביא\u0006\u0005],\u0006 \u0003אבל גלוחי בעי\u0004 \u0005[לגלח צריך\u0006\u0005]!\u0006 ודוחים: אפשר לומר כי בסגנון של \u0003\"מה טעם\" קאמר\u0004 \u0005[אומר,\u0006 נשנתה ההלכה\u0005]\u0006 וכך יש להבין: \u0003מה טעם\u0004 נזיר זה \u0003אינו מביא קרבן טומאה —\u0004 \u0003משום\u0004 ש\u0003לא בעי גלוחי\u0004 \u0005[צריך לגלח\u0006\u0005].\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 ראיה אחרת ממקור אחר: \u0003אין\u0004 הבדל \u0003בין טמא שנזר לנזיר טהור שנטמא אלא\u0004 ש\u0003טמא שנזר —\u0004 \u0003שביעי שלו\u0004 (של ימי טהרתו מן המת) \u0003עולה לו מן המנין\u0004 של ימי נזירות טהרתו שעליו למנות, \u0003ונזיר טהור שנטמא —\u0004 \u0003אין שביעי שלו עולה לו מן המנין\u0004 החדש של ימי נזירותו שעליו למנות. ונדייק מכאן: \u0003מאי לאו\u0004 \u0005[האם לא\u0006\u0005]\u0006 \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003לתגלחת —\u0004 \u0003זה וזה שוין,\u0004 שמכל מקום צריך לגלח? ודוחים: \u0003לא,\u0004 אפשר לומר: \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003למלקות זה וזה שוין.\u0004","ושואלים: \u0003אבל תגלחת מאי\u0004 \u0005[מה\u0006\u0005]\u0006 יהא הדין לפי זה — \u0003זה\u0004 (נזיר שנטמא) \u0003מגלח, וזה\u0004 (טמא שנזר) \u0003אינו מגלח?\u0004 אם כן \u0003ליתנייה\u0004 \u0005[שישנה אותו\u0006\u0005]\u0006 הבדל זה גם כן! ומשיבים: \u0003תנא\u0004 \u0005[שנה\u0006\u0005]\u0006 \u0003שביעי שלו וכל מילי\u0004 \u0005[הדברים\u0006\u0005]\u0006 הקשורים בו. ואף דין תגלחתו נכלל בו, שכן ההלכה ששביעי עולה לו הריהי משום שאינו מגלח ואינו מביא קרבן.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 ראיה ממה ששנינו במדרש ההלכה: \u0003אין לי אלא ימי טומאתו\u0004 של נזיר שנטמא \u0003שאין עולין לו מן המנין\u0004 של ימי הנזירות, \u0003ימי חלוטו\u0004 של נזיר, שנעשה בתוך נזירותו מצורע מוחלט, \u0003מנין\u0004 שאינם עולים לו למנין נזירותו? ולכאורה \u0003ודין\u0004 (סברה על פי הגיון) \u0003הוא: מה ימי טומאתו\u0004 של הנזיר, בסופם \u0003מגלח ומביא קרבן —\u0004 \u0003אף ימי חלוטו\u0004 של מצורע הלכה היא שבסופם \u0003מגלח ומביא קרבן\u0004 לצרעתו, \u0003ו\u0004מדמיון זה של הדברים, נלמד: \u0003מה ימי טומאתו אין עולין לו מן המנין —\u0004 \u0003אף ימי חלוטו אין עולין לו מן המנין.\u0004","ודוחים: \u0003לא, אם אמרת בימי טומאתו, שכן מבטל בהן את הקודמין\u0004 אף ימים שנהג קודם לכן נזירותו בטהרה — \u0003לפיכך אין עולין לו מן המנין, תאמר בימי חלוטו שאינו מבטל את הקודמין,\u0004 שאם נותרו שלושים ימים לגידול שיער אינו צריך לחזור ולמנות את הימים שלפני צרעתו, \u0003לפיכך\u0004 אפשר לומר ש\u0003עולין לו מן המנין.\u0004","כנגד זה טוענים: \u0003אמרת, ומה נזיר\u0004 שהיה \u0003בקבר\u0004 (במקום טמא) \u0003ששערו ראוי לתגלחת\u0004 של נזירות — \u0003אין עולין לו מן המנין, ימי חלוטו שאין ראוי לתגלחת\u0004 של נזירות, שהרי עליו לגלח תגלחת מצורע קודם לכן, \u0003לא כל שכן שאין עולין לו מן המנין?\u0004 עד כאן לשון הברייתא.","וממנה נסיק: \u0003מאי לאו\u0004 \u0005[האם לא\u0006\u0005]\u0006 מדובר שם במי שנזר בבית קברות, ועליו אומרת הברייתא ששערו ראוי ל\u0003תגלחת טומאה?\u0004 ונלמד מכאן שמי שנזר בהיותו בבית הקברות צריך לגלח שערו! ודוחים: \u0003לא,\u0004 מדובר ב\u0003תגלחת טהרה,\u0004 שאם נטהר אחר כך והשלים את ימי נזירותו — מגלח לבסוף את שערו בטהרה, ובכלל זה גם השיער שצמח בימי טומאתו הקודמים. ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר\u0006\u0005]\u0006 לומר,"],["\u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך\u0006\u0005]\u0006 לומר שב\u0003תגלחת טומאה\u0004 מדובר, וכי מצורע בסוף \u0003ימי חלוטו מי לא בעי\u0004 \u0005[האם אינו צריך\u0006\u0005]\u0006 \u0003תגלחת?\u0004 שהרי בסוף ימי חלוטו, כשנרפא הנגע, מתגלח המצורע, ואם כן אף בו יש תגלחת טומאה. ואיך אפשר לומר בו שאינו ראוי לתגלחת? אלא בוודאי מדובר בתגלחת טהרה. ודוחים: \u0003לא,\u0004 מכאן אין ראיה, כי אין מדובר פה בתגלחת של צרעת, אלא \u0003תגלחת\u0004 של \u0003נזירות קתני\u0004 \u0005[שנה\u0006\u0005].\u0006 שהמצורע צריך קודם להתגלח לצרעתו, ואינו ראוי לתגלחת נזיר.","ומביאים ראיה אחרת, \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 ממה ששנינו על הכתוב \u0003\"וטמא ראש נזרו\u0004 וגלח ראשו ביום טהרתו ביום השביעי יגלחנו\u0003\"\u0004 (במדבר ו, ט), ונאמר שם בדרך מדרש הלכה: \u0003ב\u0004נזיר \u0003טהור שנטמא הכתוב מדבר, שהוא טעון\u0004 (חייב) \u0003העברת שער\u0004 (גילוח) \u0003והבאת ציפרין\u0004 (\"וביום השמיני יביא שתי תורים\". במדבר ו, י), \u0003ו\u0004בא הדבר \u0003לפטור את הנזיר\u0004 שנזר \u0003בקבר\u0004 (בבית הקברות), כלומר, במקום טומאה — \u0003שאין טעון העברת שער והבאת ציפרין.\u0004","שהיה מקום לטעון כנגד זה: \u0003והלא\u0004 לכאורה \u0003דברים\u0004 אלו שאתה משמיענו לפטור, יש ללומדם לחייבו בדרך \u0003קל וחומר: ומה\u0004 נזיר \u0003טהור\u0004 מתחילה \u0003שנטמא\u0004 הריהו \u0003טעון העברת שער והבאת ציפרין, מי שהיה טמא מתחלה\u0004 כאשר קיבל עליו נזירותו — \u0003אינו דין שיהא טעון העברת שער והבאת ציפרין?\u0004","\u0003תלמוד לומר: \"וטמא ראש נזרו\",\u0004 דווקא \u0003במי שהיה\u0004 נזיר \u0003טהור ונטמא\u0004 אחר כך \u0003הכתוב מדבר,\u0004 שהוא מטמא עכשיו את השיער שהקדיש לנזירות, \u0003שיהא טעון העברת שער והבאת ציפרין, ו\u0004בא הלימוד בכתוב \u0003לפטור את הנזיר בקבר\u0004 שהוא מתחילתו טמא. \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 תשובה לשאלה, שנזיר טמא מעיקרו אינו צריך לגלח.","בעיה זו נפתרה, אלא שבאים מעתה לברר דינים אחרים הנוגעים לטמא שנזר. ושואלים: \u0003מאן תנא הא\u0004 \u0005[מי שנה זו\u0006\u0005]\u0006 שהובאה מקודם, \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים\u0006\u0005]\u0006 במהלך הדיון: \u0003אין בין טמא שנזר לנזיר טהור שנטמא, אלא שטמא שנזר —\u0004 \u0003שביעי שלו\u0004 (של ימי טהרתו מן המת) \u0003עולה לו מן המנין\u0004 של ימי נזירות הטהרה שעליו למנות מחדש, \u0003ונזיר טהור שנטמא —\u0004 \u0003אין שביעי שלו עולה לו מן המנין,\u0004 ונזירות טהרתו נמנית מיום המחרת?","\u0003אמר רב חסדא:\u0004 זו שיטת \u0003רבי היא,\u0004 ש\u0003אמר רבי: אין נזירות טהרה חלה אלא עד שמיני,\u0004 כלומר, יום אחד לאחר שנטהר הנזיר מטומאתו. \u0003דאי תימא\u0004 \u0005[שאם תאמר\u0006\u0005]\u0006 ששיטת \u0003ר' יוסי בר' יהודה היא —\u0004 \u0003האמר\u0004 \u0005[הרי אמר\u0006\u0005]\u0006 \u0003נזירות\u0004 של \u0003טהרה משביעי הוא דחיילא\u0004 \u0005[שחלה\u0006\u0005].\u0006","ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 שיטת \u0003רבי, ומאי\u0004 \u0005[ומה\u0006 היא\u0005]\u0006 שיטת \u0003ר' יוסי בר' יהודה\u0004 שהזכיר רב חסדא — \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 נאמר בנזיר שנטמא ונטהר \u0003\"וקדש את ראשו ביום\u0004 \u0003ההוא\"\u0004 (במדבר ו, יא) — והכוונה היא: \u0003ביום הבאת קרבנותיו\u0004 שהוא ביום השמיני לטהרתו, מקדש מחדש את ראשו בנזירות, אלו \u0003דברי רבי. ר' יוסי בר' יהודה אומר: ביום תגלחתו\u0004 שהוא היום השביעי לטהרתו הוא מקדש ראשו בנזירות.","ובאותו ענין מביאים עוד: \u0003והא דתנן\u0004 \u0005[וזו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003נזיר שנטמא טומאות הרבה\u0004 רצופות, זו אחר זו — \u0003אינו מביא אלא קרבן אחד, מאן תנא\u0004 \u0005[מי שנה\u0006\u0005]\u0006 ברייתא זו? \u0003אמר רב חסדא:\u0004 דעת \u0003ר' יוסי בר' יהודה היא, דאמר\u0004 \u0005[שאומר\u0006\u0005]:\u0006 \u0003נזירות טהרה\u0004 מיום \u0003שביעי חיילא\u0004 \u0005[חלה\u0006\u0005]\u0006 \u0003ו\u0004לפיכך \u0003משכחת לה\u0004 \u0005[יכול אתה למצוא אותה\u0006\u0005]\u0006 הלכה של טומאות רבות רצופות שנזיר נטמא בהן \u0003כגון שנטמא בשביעי, וחזר ונטמא בשביעי. ומני\u0004 \u0005[ו\u0006כשיטת מי היא\u0005]\u0006 שיטת \u0003ר' יוסי בר' יהודה היא,\u0004 שלדעתו \u0003כיון\u0004 ש\u0003לא יצא\u0004 (הגיעה) עדיין \u0003שעה הראויה להביא קרבן\u0004 (שהרי מביא קרבנו רק ביום השמיני), אם חזר ונטמא — \u0003אינו חייב אלא קרבן אחד.\u0004","\u0003דאי תימא\u0004 \u0005[שאם תאמר\u0006\u0005]\u0006 ששיטת \u0003רבי היא,\u0004 כיצד נעמיד הלכה זו: \u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 מדובר כאן ש\u0003נטמא בשביעי וחזר ונטמא בשביעי וחזר ונטמא בשביעי\u0004 — הרי לשיטת רבי חלה עליו נזירות שניה רק מן היום השמיני והלאה, ואם כן \u0003כולהו\u0004 \u0005[\u0006כל הטומאות כולן\u0005]\u0006 \u0003טומאה\u0004 אחת \u0003אריכתא\u0004 \u0005[ארוכה\u0006\u0005]\u0006 \u0003היא,\u0004 שהרי עדיין לא יצא מכלל טומאה שבה, ואין כאן טומאות הרבה. \u0003ואי\u0004 \u0005[ואם\u0006\u0005]\u0006 מדובר ש\u0003נטמא בשמיני וחזר ונטמא בשמיני —\u0004 \u0003הרי\u0004 ביום השמיני כבר \u0003יצתה\u0004 (יצאה) \u0003שעה שראויה להביא\u0004 בה \u0003קרבן,\u0004 שביום השמיני כבר חל עליו החיוב להביא קרבן נזיר, ואם נטמא אז — צריך להביא קרבן אחר.","ושואלים לעיקר הדברים: \u0003מאי טעמא\u0004 \u0005[מה הטעם\u0006\u0005]\u0006 של \u0003רבי\u0004 שמונה מן היום השמיני? ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 \u0003\"\u0004ועשה הכהן (תור) אחד לחטאת ואחד לעולה \u0003וכפר עליו מאשר חטא על הנפש\"\u0004 (במדבר ו, יא), \u0003והדר\u0004 \u0005[וחזר\u0006\u0005]\u0006 ואמר מיד אחר כך \u0003\"וקדש את ראשו\",\u0004 ומכאן שאין נזירות טהרה מתחילה אלא לאחר שהביא קרבנותיו. \u0003ור' יוסי בר' יהודה\u0004 אומר על כך: \u0003אם כן,\u0004 אם זו כוונת הכתוב, שנזירותו מתחילה רק ביום השמיני — \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב\u0006\u0005]\u0006 רק \u0003\"וקדש את ראשו\",\u0004 ולא יוסיף דבר, שהרי אותו פסוק מדבר בהבאת הקרבנות, שהיא ביום השמיני."],["\u0003\"ביום ההוא\" למה לי?\u0004 אלא, \u0003אם אינו ענין ל\u0004יום ה\u0003שמיני,\u0004 שאין צורך לומר \"ביום ההוא\" שהרי בו מדובר, \u0003תנהו ענין ל\u0004יום ה\u0003שביעי\u0004 והכוונה: \"ביום ההוא\" — ביום שהשלים ימי טהרתו. ושואלים: \u0003ו\u0004לדעת \u0003רבי נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר\u0006\u0005]\u0006 \u0003\"ביום ההוא\"\u0004 ומה למד הוא ממילים נוספות אלה? ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך רבי:\u0004 הכתוב \u0003ההוא להכי\u0004 \u0005[לכך\u0006\u0005]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא\u0006\u0005] —\u0006 \u0003לומר לך: אף על פי\u0004 ש\u0003לא הביא קרבנותיו\u0004 מתחיל למנות נזירות טהרה מן היום השמיני. ולכן ההדגשה \"וקידש את ראשו ביום ההוא\" שהדבר תלוי ביום ולא בקרבן.","ושואלים: \u0003ורב חסדא מאי דוחקיה לאוקמיה\u0004 \u0005[מה דוחקו להעמיד\u0006\u0005]\u0006 משנה זו דווקא \u0003כר' יוסי בר' יהודה? לוקמה\u0004 \u0005[שיעמיד אותה\u0006\u0005]\u0006 שמדובר \u0003כגון\u0004 ש\u0003נטמא דחזיא\u0004 \u0005[שראה\u0006\u0005]\u0006 כל פעם טומאה \u0003בליל שמיני,\u0004 ויש כאן מצד אחד טומאות הרבה, כיון שחלה עליו כבר נזירות טהרה מאותו זמן. ובכל זאת אינו מביא אלא קרבן אחד על כולן משום שבכל פעם היתה הטומאה בלילה, בזמן שאין ראוי עדיין להביא בו קרבן על הטומאה הקודמת, שהרי אין קרבן קרב אלא ביום. \u0003ו\u0004אם כן יתפרש שהמשנה כשיטת \u0003רבי היא!\u0004","ומציעים: \u0003מ\u0004תוך זה ש\u0003לא מוקים לה\u0004 \u0005[העמיד אותה\u0006\u0005]\u0006 \u0003כרבי\u0004 ובדרך הסבר זו, \u0003לימא קסבר\u0004 \u0005[האם לומר ש\u0006הוא, רב חסדא, סבור\u0005]\u0006 כי \u0003ליליא לאו\u0004 \u0005[לילה לא\u0006\u0005]\u0006 \u0003מחוסר זמן הוא\u0004 נחשב, שאף שאינו יכול להביא קרבנו בפועל, אינו נקרא מחוסר זמן, אלא הוא נחשב כחלק מן היום הראוי להבאת קרבן, ולכן הנטמא בערב שלפני יום שמיני דינו כנטמא ביום השמיני עצמו, שצריך להביא קרבן נוסף?","\u0003אמר רב אדא בר אהבה:\u0004 יש לדחות את הדברים, שהרי אף אם היה רב חסדא סבור שלילה מחוסר זמן, לא יכול היה להעמיד את המשנה כרבי, שכן הקרבן והנזירות החדשה \u0003הא בהא תליא\u0004 \u0005[זה בזה תלוי\u0006\u0005],\u0006 \u0003אי אמרת\u0004 \u0005[אם אומר אתה\u0006\u0005]\u0006 \u0003ליליא\u0004 \u0005[הלילה\u0006\u0005]\u0006 \u0003מחוסר זמן,\u0004 אם כן \u0003אימת מיחזי\u0004 \u0005[מתי\u0006 הוא נעשה ראוי\u0005]\u0006 \u0003לקרבן —\u0004 \u0003לצפרא\u0004 \u0005[בבוקר\u0006\u0005]\u0006 בלבד, בהתאם לכך \u0003נזירות נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003לא חיילא\u0004 \u0005[חלה\u0006\u0005]\u0006 \u0003עד צפרא\u0004 \u0005[הבוקר\u0006\u0005].\u0006 \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה\u0006\u0005]\u0006 ש\u0003ליליא\u0004 \u0005[הלילה\u0006\u0005]\u0006 \u0003אינו מחוסר זמן\u0004 וכבר נתחייב בקרבן — אם כן \u0003נזירות טהרה חיילא מאורתא\u0004 \u0005[חלה מהערב\u0006\u0005],\u0006 ובטומאה זו שנטמא בלילה מתחייב בקרבן נוסף. ואם כן, בכל אופן שנדון בהלכה של מחוסר זמן בלילה, אי אפשר להעמיד את המשנה כשיטת רבי, וממילא גם אי אפשר ללמוד מכאן על דעתו של רב חסדא.","\u0003גופא\u0004 \u0005[לגופא\u0006\u0005]\u0006 של הלכה שהזכרנו, מביאים ברייתא: נזיר שנטמא וחזר ו\u0003נטמא בשביעי\u0004 לטהרתו, \u0003וחזר ונטמא בשביעי —\u0004 \u0003אינו מביא אלא קרבן אחד. נטמא בשמיני\u0004 \u0003וחזר ונטמא בשמיני —\u0004 \u0003מביא קרבן על כל אחד ואחד\u0004 מהפעמים שנטמא. ומכל מקום \u0003מתחיל ומונה מיד\u0004 ביום השמיני לנזירות טהרה, אף שלא הביא קרבנותיו, אלו \u0003דברי ר' אליעזר.\u0004","\u0003וחכמים אומרים:\u0004 אם לא הספיק להביא קרבן ביום השמיני עד שנטמא, הרי זו כטומאה ארוכה, ומביא \u0003קרבן אחד על הכל,\u0004 על כל הפעמים שנטמא, \u0003עד שיביא\u0004 קרבן \u0003חטאתו\u0004 לגמר נזירות הטומאה, שרק אז מתחיל למנות את הנזירות הבאה. לפיכך, \u0003הביא חטאתו ונטמא, והביא חטאתו ונטמא —\u0004 \u0003מביא קרבן על כל אחד ואחד. הביא חטאתו ולא הביא אשמו\u0004 קרבן אשם שמביא נזיר טמא — \u0003מונה,\u0004 מתחיל למנות את מנין הימים של נזירות הטהרה.","\u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר: כשם שחטאתו עיכבתו\u0004 מלהתחיל מנין ימי נזירות שניה, \u0003כן אשמו מעכבו,\u0004 ואם נטמא שוב עד שלא הביא אשם — מביא קרבן אחד על הכל.","שואלים: \u0003בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003ל\u0004דעת \u0003ר' אליעזר\u0004 טעמו כי \u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 \u0003\"וקדש את ראשו ביום ההוא\"\u0004 (במדבר ו, יא), לומר: \u0003אף על פי\u0004 ש\u0003לא הביא קרבנותיו,\u0004 שהיום השמיני הוא הקובע לתחילת נזירות הטהרה, ולא הבאת הקרבנות. \u0003ורבנן\u0004 \u0005[וחכמים\u0006\u0005]\u0006 סבורים כי הכתוב \u0003\"\u0004ביום \u0003ההוא\"\u0004 בא למעט, ולומר \u0003אף על פי\u0004 ש\u0003לא הביא אשמו\u0004 מונה מן היום ההוא, אבל קרבן חטאת חייב להביא.","\u0003אלא\u0004 לדעת \u0003ר' ישמעאל\u0004 הכתוב \u0003\"\u0004ביום \u0003ההוא\" למה לי?\u0004 הרי לשיטתו הדבר תלוי בקרבן ולא ביום! ומשיבים: \u0003אמר\u0004 \u0005[יכול היה לומר\u0006\u0005]\u0006 \u0003לך\u0004 ר' ישמעאל: \u0003\"\u0004ביום \u0003ההוא\"\u0004 בא ללמד ש\u0003אף על פי\u0004 ש\u0003לא הביא עולתו,\u0004 מתחיל למנות ואין העולה מעכבת. \u0003ורבנן\u0004 \u0005[וחכמים\u0006\u0005]\u0006 אומרים על כך: \u0003עולה לא בעי מיעוטא\u0004 \u0005[צריכה מיעוט\u0006\u0005]\u0006 מיוחד בכתוב להודיע שאינה מעכבת, ומדוע — \u0003דורון\u0004 (מתנה) \u0003בעלמא\u0004 \u0005[בלבד\u0006\u0005]\u0006 \u0003הוא\u0004 ואיננה חלק מכפרתו.","ומסבירים עוד: \u0003מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים\u0006\u0005]\u0006 שסבורים שרק הבאת החטאת מעכבת ממנין חדש של ימי נזירות? \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 נאמר בנזיר שנטמא \u0003\"והזיר לה' את ימי נזרו והביא כבש בן שנתו לאשם\"\u0004 (במדבר ו, יב), \u0003מה תלמוד לומר?\u0004 והרי נוהג הוא בנזירות חדשה רק לאחר שיקריב את כל קרבנותיו! אלא, \u0003לפי שמצינו שכל אשמות שבתורה שהן מעכבין\u0004 את הכפרה, ולפני שהביא את האשם עדיין הוא מחוסר כפרה ואינו יכול לאכול בקדשים, \u0003יכול אף\u0004 אשם \u0003זה מעכבו\u0004 ממנין חדש לנזירותו —"],["\u0003תלמוד לומר: \"והזיר... והביא\"\u0004 (במדבר ו, יב), לומר: \u0003אף על פי\u0004 ש\u0003לא הביא\u0004 את אשמו — כבר \u0003הזיר,\u0004 ומתחיל למנות נזירות הטהרה. ואת טעמו של \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה\u0004 כך יש לומר, הכתוב \u0003אומר: \"והזיר... והביא\"\u0004 ופירושו: \u0003אימתי הזיר,\u0004 מתי נחשבת לו נזירות חדשה — \u0003בזמן שהביא\u0004 כבר את אשמו.","ושואלים: \u0003מאן תנא להא דתנו רבנן\u0004 \u0005[מי שנה את זו ששנו חכמים\u0006\u0005]:\u0006 \u0003אשה שנדרה בנזיר ונטמאה,\u0004 שצריכה להביא חטאת העוף, עולת העוף ואשם, \u0003ואחר כך הפר לה בעלה\u0004 את נדר הנזירות — \u0003מביאה חטאת העוף, ואינה מביאה עולת העוף.\u0004","\u0003אמר רב חסדא:\u0004 שיטת \u0003ר' ישמעאל\u0004 בנו של ר' יוחנן בן ברוקא \u0003היא.\u0004 שקרבן עולה בלבד אינו מעכב קבלת הנזירות, וכיון שבטלה נזירותה על ידי הפרת הבעל — לא תביאנו כלל.","ושואלים: \u0003מאי קסבר\u0004 \u0005[מה סבור\u0006\u0005]\u0006 תנא זה? \u0003אי קסבר\u0004 \u0005[אם סבור\u0006 הוא\u0005]\u0006 שה\u0003בעל\u0004 בהפרתו \u0003מיעקר עקר\u0004 \u0005[עוקר\u0006\u0005]\u0006 את הנדר מעיקרו, ונחשב כאילו לא נזרה אשתו כלל — אם כן \u0003חטאת העוף נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003לא לייתי\u0004 \u0005[תביא\u0006\u0005],\u0006 שהרי לא היתה נזירה כלל ואינה חייבת בחטאת. ומצד שני, \u0003אי קסבר\u0004 \u0005[אם סבור\u0006\u0005]\u0006 הוא שה\u0003בעל\u0004 בהפרתו \u0003מיגז גייז\u0004 \u0005[גוזז\u0006\u0005]\u0006 את הנדר, כלומר, שהנדר בטל משעת ההפרה והלאה, אבל היתה לו חלות כלשהי מעיקרה, אם כן, אם נטמאה האשה בזמן נזירותה \u0003עולת העוף נמי לייתי\u0004 \u0005[גם כן תביא\u0006\u0005]\u0006 על מה שנהגה נזירות! ומשיבים: \u0003לעולם\u0004 תפרש כי \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 ש\u0003בעל מיעקר עקר\u0004 \u0005[עוקר\u0006 את הנדר מעיקרו\u0005],\u0006 \u0003ו\u0004מדוע עליה להביא חטאת? \u0003ר' ישמעאל סבר לה\u0004 \u0005[סבור\u0006 בענין זה\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' אלעזר הקפר.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 \u0003ר' אלעזר הקפר ברבי\u0004 (הגדול) \u0003אומר: מה תלמוד לומר\u0004 בנזיר \u0003\"וכפר עליו מאשר חטא על\u0004 \u0003הנפש\"\u0004 (במדבר ו, יא)? \u0003וכי באיזו נפש חטא זה\u0004 בנזירותו? \u0003אלא\u0004 מפני \u0003שציער\u0004 את \u0003עצמו מן היין\u0004 — הרי זה חוטא בנפשו של עצמו, ולכן צריך להביא קרבן חטאת על עצם הנזירות, שציער את גופו. \u0003ו\u0004יש ללמוד מכאן ב\u0003קל וחומר: ומה זה\u0004 ש\u0003לא ציער עצמו אלא מן היין נקרא חוטא, המצער עצמו\u0004 בסיגופים ותעניות \u0003מכל דבר —\u0004 \u0003על אחת כמה וכמה\u0004 שנקרא חוטא. ולדרך זו סבור ר' ישמעאל שאף אשה זו כיון שבפועל ציערה עצמה בנזירות שנהגה — עליה להביא את קרבן החטאת, אף שלא היתה נזירה ממש, בגלל הפרת בעלה.","ולעצם דברי ר' אלעזר הקפר שואלים: \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003בנזיר טמא כתיב\u0004 \u0005[נאמר\u0006\u0005]\u0006 פסוק זה \u0003ואנן\u0004 \u0005[ואנו\u0006\u0005]\u0006 \u0003אפילו נזיר טהור קאמרינן\u0004 \u0005[אומרים אנו\u0006\u0005]\u0006 שגם הוא מביא קרבן חטאת! משיבים: \u0003קסבר\u0004 \u0005[סבור\u0006\u0005]\u0006 \u0003ר' אלעזר הקפר נזיר טהור נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003חוטא הוא, והיינו טעמא דכתיב\u0004 \u0005[וזה הטעם שנאמר\u0006\u0005]\u0006 ביטוי זה (\"מאשר חטא על הנפש\") דווקא \u0003בנזיר טמא\u0004 ולא בנזיר טהור — \u0003הואיל ושנה בחטא,\u0004 שבמה שנטמא ונתחייב שוב נזירות — נמצא מצער עצמו פעם נוספת, והיה עליו להיזהר ביותר שלא ישוב ויצער עצמו.","שנינו במשנה שנזיר שנדר בבית הקברות, אם \u0003יצא ונכנס —\u0004 \u0003עולין לו\u0004 אותם ימים ששהה בחוץ \u0003מן המנין\u0004 של נזירות טהרה, ולפיכך אם נכנס שוב חייב בקרבן טומאה. \u0003קתני\u0004 \u0005[שנה\u0006\u0005]\u0006 \u0003עולין לו מן המנין,\u0004 ותוהים: \u0003משום\u0004 שרק \u0003יצא\u0004 ממקום טמא \u0003חל עליה\u0004 \u0005[חלה עליו\u0006\u0005]\u0006 \u0003נזירות?\u0004 הרי עדיין טמא הוא! \u0003אמר שמואל:\u0004 מדובר כאן \u0003כגון שיצא ו\u0004נטהר כדין: \u0003הזה\u0004 שהיזו עליו מי פרה אדומה ביום השלישי, \u0003ושנה\u0004 שהיזו עליו שנית ביום השביעי, כדי להיטהר מטומאת מת, \u0003וטבל,\u0004 ואחר כך נכנס שוב לבית הקברות. שכיון שנטהר חלה עליו הנזירות.","ועוד שואלים: לפי דיוק דברי המשנה, שהזכירה דווקא מקרה שחזר ונכנס לבית הקברות, \u0003אלא\u0004 רק אם חזר ו\u0003נכנס\u0004 למקום טמא \u0003הוא\u0004 ש\u0003עולין לו מן המנין, לא נכנס —\u0004 \u0003אין עולין לו מן המנין?!\u0004 ומשיבים: בלשון \u0003לא מיבעיא\u0004 \u0005[נצרכה\u0006\u0005]\u0006 \u0003קאמר\u0004 \u0005[הוא אומר\u0006\u0005],\u0006 וכך משמעות הדברים: \u0003לא מיבעיא\u0004 \u0005[נצרכה\u0006\u0005]\u0006 לומר אם \u0003יצא\u0004 ונהג נזירותו כרגיל שעולים לו הימים למנין נזירותו, \u0003אלא אפילו נכנס\u0004 מיד לאחר טהרתו למקום טומאה גם כן \u0003עולין\u0004 (נחשב) \u0003לו\u0004 אותו זמן קודם שנכנס \u0003מן המנין,\u0004 ויתחייב בקרבן טומאה אם נכנס שוב.","מסופר: \u0003אמרו ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רב כהנא ורב אסי לרב: מאי טעמא לא מפרשת לן כהלין מילי\u0004 \u0005[מה טעם,\u0006 משום מה אין אתה מפרש לנו כאותם הדברים\u0005]\u0006 שאמר שמואל, שהסביר ופירש את משמעות המשנה? \u0003אמר להון\u0004 \u0005[להם\u0006\u0005]:\u0006 \u0003אמינא דלמא לא צריכיתו\u0004 \u0005[אמרתי\u0006 בלבי, שמא אין אתם צריכים לכך\u0005],\u0006 שהיה נראה לי שדבר זה פשוט, ואין צריך לאומרו.","שנינו במשנה ש\u0003ר' אליעזר אומר: לא בו ביום,\u0004 שאם נטמא שוב ביום הראשון שנטהר בו — אינו סותר את נזירותו ואינו מביא קרבן טומאה, \u0003שנאמר\u0004 בנזיר שמביא קרבן טומאה: \u0003\"והימים הראשנים יפלו\"\u0004 (במדבר ו, יב), ללמד: \u0003עד שיהיו ימים ראשונים. אמר עולא: לא אמר ר' אליעזר\u0004 דין זה \u0003אלא בטמא שנזר\u0004 שלא חלה עליו נזירות מתחילה, \u0003אבל בנזיר טהור\u0004 ש\u0003נטמא —\u0004 \u0003אפילו\u0004 היה נזיר רק \u0003יום אחד —\u0004 \u0003סותר\u0004 את היום האחד של נזירותו, ומביא קרבן טומאה, ומתחיל במנין נזירות חדשה."],["\u0003אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם\u0006\u0005]\u0006 של \u0003ר' אליעזר\u0004 לפי שיטת עולא? — \u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 בנזיר טמא: \u0003\"\u0004והימים הראשונים יפלו \u0003כי טמא נזרו\"\u0004 (במדבר ו, יב), והוא מפרש: מדוע יפלו הימים הראשונים — \u0003משום\u0004 ש\u0003בטומאה נזר,\u0004 שכבר מתחילה היתה נזירותו בטומאה.","\u0003איתיביה\u0004 \u0005[הקשה לו\u0006\u0005]\u0006 \u0003אביי\u0004 לרבא, שהלך בשיטת עולא, ממה ששנינו: האומר \u0003\"הריני נזיר מאה יום\" ונטמא\u0004 מיד \u0003בתחלת\u0004 מנין ה\u0003מאה, יכול יהא סותר\u0004 נזירותו ומונה מחדש? \u0003תלמוד לומר: \"והימים הראשנים יפלו\"\u0004 (במדבר ו, יב), לומר: \u0003עד שיהו לו ימים ראשונים, וזה אין לו\u0004 ימים \u0003ראשונים.\u0004","\u0003נטמא בסוף מאה,\u0004 כלומר, ביום המאה, \u0003יכול יהא סותר? תלמוד לומר: \"והימים הראשנים יפלו\" —\u0004 \u0003מכלל\u0004 שאמר \"ראשונים\" משמע \u0003דאיכא\u0004 \u0005[שיש\u0006\u0005]\u0006 ימים אחרים שהם \u0003אחרונים, וזה אין לו אחרונים,\u0004 שהרי כבר השלים נזירותו. \u0003נטמא ביום מאה חסר אחת, יכול לא יהא סותר —\u0004 \u0003תלמוד לומר: \"והימים הראשנים יפלו\"\u0004 — \u0003מכלל דאיכא\u0004 \u0005[שיש\u0006\u0005]\u0006 \u0003אחרונים, וזה יש לו ראשונים ואחרונים.\u0004","\u0003והא\u0004 \u0005[ו\u0006דבר זה\u0005]\u0006 ששנו בברייתא, \u0003בטמא שנזר לא מצית אמרת\u0004 \u0005[אין אתה יכול לומר\u0006\u0005],\u0006 \u0003מדקתני\u0004 \u0005[ממה ש\u0006הוא שונה\u0005]\u0006 \u0003\"הריני נזיר מאה\" ונטמא בתחלת מאה,\u0004 הרי מדובר במי שהחל בנזירות ואחר כך נטמא, \u0003וקתני\u0004 \u0005[ושנה\u0006\u0005]\u0006 \u0003\"עד שיהו לו ימים ראשונים\"\u0004 ומכאן שלדעת ר' אליעזר נאמר דין זה אפילו בנזיר טהור שנטמא, והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006\u0005]\u0006 לעולא ונדחו דבריו.","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רב פפא לאביי: הלין\u0004 \u0005[אותם\u0006\u0005]\u0006 \u0003ימים דקאמרינן\u0004 \u0005[שאמרנו\u0006\u0005]\u0006 לשיטת ר' אליעזר, שצריך שיהו ימים ראשונים בטהרה, האם הכוונה היא \u0003דנפק חד ומתחילין תרין\u0004 \u0005[שיוצא,\u0006 שנגמר, יום אחד, ומתחילים שניים\u0005]\u0006 ואם נטמא ביום השני סותר, \u0003או דלמא דנפקין תרין ומתחילין תלתא\u0004 \u0005[שמא שיוצאים,\u0006 נגמרים, שניים ומתחילים שלושה\u0005],\u0006 שרק אם נטמא לאחר שהחל היום השלישי סותר? \u0003לא הוה בידיה\u0004 \u0005[היתה בידו\u0006\u0005]\u0006 של אביי תשובה, \u0003אתא שייליה\u0004 \u0005[הלך\u0006 רב פפא ושאל\u0005]\u0006 את \u0003רבא. אמר ליה\u0004 \u0005[לו\u0006\u0005]:\u0006 \u0003\"יפלו\" כתיב\u0004 \u0005[נאמר\u0006\u0005]\u0006 לשון רבים, ומיעוט רבים שניים.","ומעירים: \u0003ואיצטריך למיכתב\u0004 \u0005[והוצרך לכתוב\u0006\u0005]\u0006 \u0003\"ימים\" ואיצטריך למיכתב\u0004 \u0005[והוצרך לכתוב\u0006\u0005]\u0006 \u0003\"יפלו\", דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה\u0006\u0005]\u0006 רק \u0003\"ימים\" ולא כתב\u0004 \u0005[היתה כותבת\u0006\u0005]\u0006 \u0003\"יפלו\", הוה אמינא\u0004 \u0005[הייתי אומר\u0006\u0005]:\u0006 \u0003עד דנפקין תרין ועיילין תלתא\u0004 \u0005[שיוצאים שניים ונכנסים שלושה\u0006\u0005],\u0006 לכן \u0003כתב רחמנא\u0004 \u0005[כתבה תורה\u0006\u0005]\u0006 \u0003\"יפלו\". ואי כתב\u0004 \u0005[ואם היתה\u0006 התורה כותבת\u0005]\u0006 רק \u0003\"יפלו\" ולא כתב\u0004 \u0005[היתה כותבת\u0006\u0005]\u0006 \u0003\"ימים\", הוה אמינא\u0004 \u0005[הייתי אומר\u0006\u0005]\u0006 \u0003אפילו\u0004 יום \u0003חד\u0004 \u0005[אחד\u0006\u0005],\u0006 כלומר, אפילו אם נטמא ביום הראשון, לכן \u0003כתב רחמנא\u0004 \u0005[כתבה תורה\u0006\u0005]\u0006 \u0003\"ימים\",\u0004 שמיעוט רבים שניים, שדי ביום אחד ומקצת השני בלבד.","\u0003מי ש\u0004היה בחוצה לארץ, ו\u0003נזר נזירות הרבה,\u0004 כלומר, יותר משלושים יום. \u0003והשלים את נזירותו, ואחר כך בא לארץ\u0004 (ארץ ישראל) להביא קרבנותיו ולסיים את נזירותו, \u0003בית שמאי אומרים:\u0004 אף שנהג נזירות בחוץ לארץ כפי שנדר, מכל מקום הוא צריך להיות \u0003נזיר שלשים יום\u0004 בארץ ישראל כדי שתהיה לו נזירות בטהרת ארץ ישראל, \u0003ובית הילל אומרים:\u0004 הריהו צריך להיות \u0003נזיר בתחלה,\u0004 כלומר, צריך להתחיל את כל ימי נזירותו מתחילתה.","ומסופר בענין זה: \u0003מעשה בהילני המלכה שהלך בנה למלחמה, ואמרה: אם יבוא בני מן המלחמה בשלום —\u0004 \u0003אהא נזירה שבע שנים. ובא בנה מן המלחמה, והיתה נזירה שבע שנים. ובסוף שבע שנים עלתה לארץ, והורוה בית הלל\u0004 כשיטתם \u0003שתהא נזירה עוד שבע שנים אחרות. ובסוף שבע שנים\u0004 אלה \u0003נטמאת\u0004 ונהגה עוד שבע שנים של נזירות, כדין נזיר שנטמא — שסותר ומונה מחדש את נזירותו. \u0003ונמצאת\u0004 שהיתה \u0003נזירה עשרים ואחת שנה. אמר ר' יהודה: לא היתה נזירה אלא ארבע עשרה שנה\u0004 ולא עשרים ואחת.","\u0003קתני רישא\u0004 \u0005[שנה בראשה\u0006\u0005]\u0006 של המשנה: \u0003בית שמאי אומרים: נזיר שלשים יום, ובית הלל אומרים: נזיר בתחלה.\u0004 ומציעים הסבר לשיטותיהם: \u0003לימא בהא קמיפלגי\u0004 \u0005[האם לומר\u0006 שבבעיה זו הם חלוקים\u0005]\u0006 ש\u0003בית שמאי סברי\u0004 \u0005[סבורים\u0006\u0005]\u0006 בענין \u0003ארץ העמים\u0004 שגזרו עליה חכמים טומאה, ש\u0003משום גושה גזרו עליה,\u0004 כלומר, העפר של ארץ העמים הוא טמא, אבל האויר, החלל, של ארץ העמים אינו טמא. ואם כן טומאת ארץ העמים אינה טומאה חמורה, ולכן אין לומר שיהא הנזיר שנהג נזירות בחוץ לארץ נחשב כטמא ממש ולהצריכו בשל כך לנהוג מחדש את כל ימי נזירותו."],["\u0003ובית הלל סברי\u0004 \u0005[סבורים\u0006\u0005]:\u0006 ארץ העמים \u0003משום אוירא\u0004 \u0005[האויר,\u0006 החלל\u0005]\u0006 \u0003גזרו עליה,\u0004 ולכן טומאתה חמורה, ומשום כך צריך להתחיל את כל נזירותו מתחילה? ודוחים: \u0003לא,\u0004 אפשר לומר \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל\u0006\u0005]\u0006 \u0003משום גושה גזרו עליה\u0004 ואין כאן טומאה חמורה, אלא שנחלקו בפרטי הקנס, \u0003ובית שמאי סברי\u0004 \u0005[סבורים\u0006\u0005]\u0006 \u0003בסתם נזירות\u0004 שהיא של שלושים יום \u0003קניסנא\u0004 \u0005[אנו קונסים\u0006\u0005],\u0006 \u0003ובית הלל סברי\u0004 \u0005[סבורים\u0006\u0005]:\u0006 \u0003כי קניסנא\u0004 \u0005[כאשר אנו קונסים\u0006\u0005] —\u0006 \u0003בתחילת נזירות,\u0004 שצריך לחזור ולנהוג נזירות כמתחילת ימי הנזירות שקיבל על עצמו.","שנינו במשנה: \u0003מעשה בהילני המלכה\u0004 שנדרה נזירות שבע שנים, ועלתה לארץ והורוה בית הלל שתנהג נזירות עוד שבע שנים, ובסוף אותן שבע שנים נטמאה והיתה צריכה להיות נזירה עוד שבע שנים אחרות, ונהגה בסך הכל עשרים ואחת שנות נזירות. ואילו ר' יהודה סבור שנהגה נזירות רק ארבע עשרה שנה. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 כיצד להבין את דברי ר' יהודה? האם לדעתו היה המעשה \u0003בשנטמאת\u0004 בארץ ישראל, אבל לא בסוף שבע שנים, אלא בסוף שלושים יום, \"ביום מלאת\", \u0003ו\u0004ר' יהודה אמר את דבריו \u0003אליבא\u0004 \u0005[על פי שיטת\u0006\u0005]\u0006 \u0003בית שמאי\u0004 שלא היתה צריכה למנות עוד שבע שנים בארץ ישראל, אלא רק שלושים יום, ומפני שנטמאה היו בסך הכל ארבע עשרה שנות נזירות. \u0003או דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003ב\u0004ש\u0003לא נטמאת,\u0004 שכך היה המעשה — שלא נטמאת בסוף אותן שבע שנים, \u0003ו\u0004מכל מקום אמר את דבריו \u0003אליבא\u0004 \u0005[על פי שיטת\u0006\u0005]\u0006 \u0003בית הלל\u0004 שהיה עליה לנהוג שבע שנים נוספות משעלתה לארץ.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 פתרון לדבר ממה ששנינו: \u0003עלתה לארץ, והורוה בית הלל שתהא נזירה עוד שבע שנים אחרות וכו'\u0004 ונטמאה בסוף אותן שבע שנים שנתחייבה בהם בעלייתה לארץ. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 שדברי ר' יהודה הם \u0003בשנטמאת\u0004 בסוף שלושים יום של נזירות לאחר שעלתה לארץ \u0003ואליבא\u0004 \u0005[על פי שיטת\u0006\u0005]\u0006 \u0003בית שמאי,\u0004 \u0003אי הכי\u0004 \u0005[אם כך\u0006\u0005]\u0006 מדוע \u0003ר' יהודה אומר לא היתה נזירה אלא ארבע עשרה שנה?\u0004 והלא \u0003ארבע עשרה שנה ושלשים יום מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 שאם כשיטת בית שמאי הרי הם אומרים שבארץ ישראל צריך הנזיר לנהוג עוד שלושים ימי נזירות!","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא גם כן כך\u0005],\u0006 שלא ניתן להעמיד את דעת ר' יהודה לשיטת בית שמאי, \u0003ר' יהודה אומר משום ר' אליעזר:\u0004 זה ש\u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 \"ו\u0003זאת תורת הנזיר\u0004 ביום מלאת ימי נזרו\" וגו' (במדבר ו, יג), \u0003התורה אמרה: כי\u0004 \u0005[כאשר\u0006\u0005]\u0006 \u0003נטמא ביום מלאת\u0004 נזירותו, ואף אם היתה זו נזירות ארוכה — \u0003תן לו תורת נזיר\u0004 סתם, שהם שלושים יום נוספים. ולפי זה אם מדובר בשנטמאת בסוף אותם שלושים יום (ב\"יום מלאת\"), היתה צריכה להיות נזירה שלושים יום נוספים בלבד, ולא לנהוג נזירות מלאה של שבע שנים נוספות. אלא ודאי סבור הוא כבית הלל, אלא שלדעתו לא נטמאה כלל.","\u0003מי שהיו שתי כיתי עדים מעידות אותו\u0004 (עליו) עדויות שונות על נזירותו, \u0003אלו מעידים שנזר שתים\u0004 (שתי נזירויות), \u0003ואלו מעידים שנזר חמש, בית שמאי אומרים: נחלקה העדות,\u0004 וכיון שיש כאן עדויות סותרות — \u0003אין כאן\u0004 עדות כלל, ואינו נזיר. \u0003ובית הלל אומרים:\u0004 אין כאן סתירה גמורה בין העדויות כי \u0003יש בכלל חמש שתים,\u0004 ולפיכך יעשה מה שהכל מודים בו \u0003שיהא נזיר שתים.\u0004","מעירים: \u0003מתניתין\u0004 \u0005[משנתנו\u0006\u0005]\u0006 ש\u0003לא כי האי תנא\u0004 \u0005[כמו,\u0006 כשיטת תנא זה\u0005],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקא אומר: לא נחלקו בית שמאי ובית הלל על שתי כיתי עדים,\u0004 ו\u0003אחת\u0004 מהן \u0003אומרת שתים, ואחת אומרת חמש, ש\u0004לדעת הכל \u0003יש בכלל חמש שתים. על מה נחלקו\u0004 — \u0003על כת אחת\u0004 של שני עדים, ש\u0003אחד\u0004 מהם \u0003אומר שתים, ואחד אומר חמש, שבית שמאי אומרים:\u0004 באופן שכזה אנו אומרים ש\u0003נחלקה עדותן,\u0004 כיון שאין שני העדים מסכימים בעדותם אין כאן עדות כלל. \u0003ובית הלל אומרים:\u0004 מכל מקום מסכימים הם בדבר אחד, ו\u0003יש בכלל חמש שתים.\u0004","על העמדה זו של המחלוקת, בכת אחת של עדים, \u0003אמר רב: הכל מודים במונה\u0004 שיש בכך הכחשת עדות. \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רב חמא לרב חסדא: מאי קאמר\u0004 \u0005[מה אמר\u0006\u0005],\u0006 מה כוונת דבריו אלה של רב? \u0003אילימא\u0004 \u0005[אם תאמר\u0006\u0005]\u0006 שעד \u0003אחד אומר: חמש ולא שתים, ואחד אומר: שתים ולא חמש\u0004 — במקרה כזה \u0003הא קא מכחשי אהדדי\u0004 \u0005[הרי\u0006 הם מכחישים זה את זה\u0005]\u0006 ובודאי אין לסמוך על אף אחת מן העדויות! \u0003אלא:\u0004 עד \u0003אחד אומר\u0004 שאמר בקבלת נזירותו \u0003\"\u0004הריני מקבל עלי נזירות \u0003אחת ושתים\", ואחד אומר:\u0004 שאמר \u0003\"\u0004הריני מקבל עלי נזירות \u0003שלש, ארבע, חמש\"\u0004 —"],["\u0003הא\u0004 \u0005[זו\u0006\u0005]\u0006 \u0003למה לי\u0004 לומר כלל? שכן \u0003השתא\u0004 \u0005[עכשיו\u0006\u0005]\u0006 הרי \u0003יש לומר\u0004 \u0003חמירתא\u0004 \u0005[ב\u0006הלכה חמורה\u0005]\u0006 \u0003אמר רב\u0004 שגם אם היו שתי כתי עדים שכל אחת מהן דיה לחייבו בנזירות, נחלקה עדותן, \u0003קילתא\u0004 \u0005[\u0006בהלכה קלה\u0005]\u0006 בשני עדים של כת אחת, שאין בכל אחד מהם לחייבו בנזירות, אלא רק כשהם יחד \u0003לא אמר?!\u0004 ומובן שבכת אחת הרי זו כהכחשת עדות! \u0003אמרי במערבא\u0004 \u0005[אומרים בארץ ישראל\u0006\u0005]:\u0006 \u0003אין הכחשה במונה.\u0004 שכיון שאחד מונה מספר מסויים, והשני מספר גדול יותר — אין כאן דין הכחשה, אלא ודאי נכלל המספר הקטן במספר הגדול.","","\u0003מי שאמר \"הריני נזיר\" ושמע\u0004 זאת \u0003חבירו ואמר\u0004 אחריו \u0003\"ואני\",\u0004 והיה שם עוד אחד ואמר אחריו \u0003\"ואני\"\u0004 — הרי \u0003כולם נזירים.\u0004 אם \u0003הותר הראשון\u0004 מנדרו על ידי חכם — \u0003הותרו כולן.\u0004 ואולם אם \u0003הותר האחרון —\u0004 \u0003האחרון מותר וכולם אסורין. אמר\u0004 אדם \u0003\"הריני נזיר\", ושמע חבירו ואמר \"פי כפיו ושערי כשערו\" —\u0004 \u0003הרי זה נזיר.\u0004","אמר אדם \u0003\"הריני נזיר\", ושמעה\u0004 זאת \u0003אשתו ואמרה \"ואני\"\u0004 — אם רוצה \u0003מיפר\u0004 הוא \u0003את\u0004 נדר הנזירות \u0003שלה, ו\u0004מכל מקום \u0003שלו קיים,\u0004 שהרי אין נדרו תלוי בנדרה. אמרה האשה \u0003\"הריני נזירה\" ושמע בעלה ואמר \"ואני\" —\u0004 \u0003אינו יכול להפר\u0004 את נדרה, שכן על ידי כך נמצא שהוא מיפר גם את נדרו שלו, שהרי תלוי נדרו בשלה. אם אמר לאשתו \u0003\"הריני נזיר ואת\",\u0004 כלומר, גם את תהיי נזירה, \u0003ואמרה \"אמן\",\u0004 שאכן מקבלת היא נדר זה על עצמה — \u0003מיפר את שלה, ושלו קיים.\u0004 אבל אם אמרה האשה \u0003\"הריני נזירה ואתה\" ואמר \"אמן\" —\u0004 \u0003אינו יכול להפר\u0004 את נדרה.","\u0003יתיב\u0004 \u0005[ישב\u0006\u0005]\u0006 \u0003ריש לקיש קמיה\u0004 \u0005[לפני\u0006\u0005]\u0006 \u0003ר' יהודה נשיאה ויתיב וקאמר\u0004 \u0005[וישב ואמר\u0006\u0005]\u0006 בהסבר המשנה: מה ששנינו שכולם נזירים — \u0003והוא\u0004 דווקא כ\u0003שהתפיסו כולן\u0004 את נדרם \u0003ב\u0004פרק זמן ששיעורו \u0003תוך כדי דיבור\u0004 לדברי הקודם להם. ומסבירים: \u0003וכמה\u0004 הוא \u0003תוך כדי דיבור —\u0004 \u0003כדי שאלת שלום, וכמה\u0004 הוא \u0003כדי שאלת שלום —\u0004 \u0003כדי שאומר שלום תלמיד לרב,\u0004 שאומר לו \"שלום עליך רבי\". \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 ר' יהודה נשיאה לריש לקיש: \u0003תוב\u0004 \u0005[שוב\u0006\u0005]\u0006 \u0003לא שבקת רווחא לתלמידא\u0004 \u0005[הנחת רווח לתלמיד\u0006\u0005]\u0006 שיתפיס בנזירות, כגון שעבר רבו במקום באותה שעה שחבירו קיבל עליו נזירות. שכיון שצריך הוא לומר לו שלום, שוב אינו יכול להיות נזיר, שהרי זה לאחר כדי דיבור, ואילו במשנה אין מחלוקת בזה!",""],["\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא גם כן כך\u0005]:\u0006 \u0003מי שאמר \"הריני נזיר\" ושמע\u0004 זאת \u0003חבירו ושהה כדי דבור, ו\u0004אחר כך \u0003אמר \"ואני\" —\u0004 \u0003הוא,\u0004 הראשון, \u0003אסור, וחבירו מותר,\u0004 שאין נדרו תופס, כיון שהיתה הפסקה מעבר לכדי דיבור בין דבריו לדברי חבירו. \u0003וכמה\u0004 הוא שיעור \u0003כדי דבור —\u0004 \u0003כדי שאילת שלום תלמיד לרב.\u0004","ומציעים: \u0003לימא מסייעא ליה\u0004 \u0005[האם אפשר לומר שמסייע לו\u0006\u0005],\u0006 לריש לקיש, מה ששנינו במשנתנו: \u0003מי שאמר \"הריני נזיר\" ושמע חבירו ואמר \"ואני\"\u0004 ועוד אחד שמע ואמר \u0003\"ואני\",\u0004 הרי שהזכירה המשנה רק פעמיים \"ואני\", \u0003ותו\u0004 \u0005[ויותר\u0006\u0005]\u0006 \u0003לא\u0004 נזכר במשנה, משמע שאין איש נוסף יכול להחיל עוד נזירות, והטעם — מפני שיש הפסק גדול מדי מן הדיבור הראשון. ודוחים: זו אינה ראיה, וכי ה\u0003תנא כי רוכלא ליחשיב וליזיל\u0004 \u0005[כרוכל ימנה וילך\u0006\u0005]\u0006 ויאמר שוב ושוב \"ואני\" \"ואני\"?","ומקשים: אם כן, שהתנא מקצר בלשונו — \u0003וליתני חד ולשמעינן הני\u0004 \u0005[ושישנה\u0006 רק אחד וישמיענו מכאן את אלו האחרים\u0005]!\u0006 ומשיבים: \u0003הכי נמי\u0004 \u0005[כך גם כן\u0006\u0005]\u0006 היה צריך להיות, \u0003ו\u0004אולם \u0003משום דקתני סיפא\u0004 \u0005[ששנה בסוף\u0006\u0005]\u0006 \u0003הותר הראשון —\u0004 \u0003הותרו כולן, הותר האחרון —\u0004 \u0003האחרון מותר וכולן אסורין, מכלל\u0004 הדברים אנו למדים \u0003דאיכא\u0004 \u0005[שיש\u0006\u0005]\u0006 \u0003אמצעי\u0004 בין הראשון והאחרון, \u0003ומשום הכי קתני\u0004 \u0005[כך שנה\u0006\u0005]\u0006 \u0003\"ואני\" \"ואני\"\u0004 שביחד עם הראשון הריהם שלושה; ראשון, אחרון ואמצעי.","ובאותו ענין \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: האם \u0003חד בחבריה מיתפיס\u0004 \u0005[אחד בחבירו נתפס\u0006\u0005],\u0006 כלומר, כל אחד נתפס בנדרו של הקודם לו, \u0003או דלמא בקמא מיתפסי\u0004 \u0005[שמא בראשון נתפסים\u0006 כולם\u0005]?\u0006 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[למה,\u0006 לאיזה ענין להלכה יוצא הבדל מזה\u0005]\u0006 אם נאמר כצד זה או כצד זה של הבעיה — \u0003לאתפוסי ומיזל\u0004 \u0005[להתפיס וללכת\u0006 הלאה\u0005]\u0006 יותר ויותר אנשים. \u0003אי אמרת חד בחבריה מתפיס\u0004 \u0005[אם אומר אתה\u0006 כי אחד בחבירו נתפס\u0005] —\u0006 \u0003מתפסין ואזלין\u0004 \u0005[נתפסים והולכים\u0006\u0005]\u0006 \u0003לעולם,\u0004 שאם לא היה הפסק זמן בין אחד לחבירו — אפשר להמשיך כך את השרשרת כמה שירצו. \u0003ואי אמרת בקמא מתפסי\u0004 \u0005[ואם אתה אומר שבראשון\u0006 הם נתפסים\u0005]\u0006 — \u0003טפי\u0004 \u0005[יותר\u0006\u0005]\u0006 \u0003מכדי דבור\u0004 מן הראשון \u0003לא מתפסין\u0004 \u0005[נתפסים\u0006\u0005].\u0006 ואם כן \u0003מאי\u0004 \u0005[מה\u0006\u0005]\u0006 הדין?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 ראיה ממה ששנינו במשנתנו: \u0003\"הריני נזיר\" ושמע חבירו ואמר \"ואני\" \"ואני\",\u0004 שרק פעמיים הוזכר \"ואני\" \u0003ותו\u0004 \u0005[ויותר\u0006\u0005]\u0006 \u0003לא\u0004 נזכר \u0003מידי\u0004 \u0005[דבר\u0006 נוסף\u0005],\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 כי \u0003בקמא\u0004 \u0005[בראשון\u0006\u0005]\u0006 \u0003הוא דמתפסי\u0004 \u0005[שנתפסים\u0006 כולם\u0005],\u0006 \u0003דאי סלקא דעתך חד בחבריה מיתפיס\u0004 \u0005[שאם עולה על דעתך\u0006 כל אחד בחבירו נתפס\u0005]\u0006 — \u0003ליתני טובא\u0004 \u0005[שישנה יותר\u0006\u0005]\u0006 \u0003\"ואני\"!\u0004 ודוחים: מכאן אין ראיה, וכי ה\u0003תנא כי רוכלא ליחשיב וליזיל\u0004 \u0005[כרוכל ימנה וילך\u0006\u0005]?\u0006 אלא הסתפק רק בשתי דוגמאות.","ומקשים: אם לא רצה לשנות הרבה, \u0003וליתני חד ולשמעינן כולהון\u0004 \u0005[שישנה\u0006 רק \"ואני\" אחד וישמיענו מכאן את כולם\u0005]!\u0006 ומשיבים: \u0003איידי דקתני\u0004 \u0005[מתוך ששנה\u0006\u0005]\u0006 בהמשך \u0003הותר הראשון —\u0004 \u0003הותרו כולן, הותר האחרון —\u0004 \u0003האחרון מותר וכולן אסורין, מכלל דאיכא\u0004 \u0005[שיש\u0006\u0005]\u0006 \u0003אמצעי, משום הכי קתני\u0004 \u0005[כך שנה\u0006\u0005]\u0006 \u0003\"ואני\" \"ואני\"\u0004 — שיהיו לפחות שלושה, שהם הנודר הראשון ושניים שאחריו. אבל אין מכאן ראיה שאי אפשר שייתפסו יותר.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 ראיה נוספת ממה ששנינו במשנה: \u0003הותר הראשון —\u0004 \u0003הותרו כולן.\u0004 ונדייק: דווקא אם הותר \u0003ראשון הוא דשרו\u0004 \u0005[שהותרו\u0006\u0005]\u0006 כולם על ידי התרתו, \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 אם הותר ה\u0003אמצעי —\u0004 \u0003לא\u0004 הותרו אלו שאחריו, אם כן \u0003שמע מינה בקמא מתפסין\u0004 \u0005[למד מכאן שבראשון הם נתפסים\u0006\u0005],\u0006 והכל תלוי בו בלבד.","ודוחים: \u0003אימא\u0004 \u0005[\u0006יכול אני לומר\u0005]\u0006 \u0003לך: לעולם חד בחבריה מתפיס\u0004 \u0005[אחד בחבירו נתפס\u0006\u0005],\u0006 ואף אם הותר האמצעי היו אלו שאחריו מותרים. אלא \u0003ואיידי דבעי מיתנא\u0004 \u0005[ומתוך שרצה לשנות\u0006\u0005]\u0006 \u0003\"הותרו כולן\", דאי תנא\u0004 \u0005[שאם היה שונה\u0006\u0005]\u0006 דבר זה ב\u0003אמצעי,\u0004 אי אפשר לומר כך, שהרי \u0003איכא\u0004 \u0005[יש\u0006\u0005]\u0006 \u0003ראשון\u0004 ש\u0003לא משתרי\u0004 \u0005[מותר\u0006\u0005],\u0006 שהרי הוא לא התפיס באמצעי, \u0003משום הכי קתני\u0004 \u0005[כך שנה\u0006\u0005]\u0006 \u0003ראשון,\u0004 ואם כן אין מכאן ראיה.","ומציעים עוד ראיה מן המשנה: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]:\u0006 \u0003הותר האחרון —\u0004 \u0003האחרון מותר וכולן אסורין.\u0004 ויש לדייק מכאן: דווקא במקרה זה הוא בלבד מותר, ומדוע? משום \u0003דלא איכא אחרינא בתריה\u0004 \u0005[שאין אחר אחריו\u0006\u0005],\u0006 \u0003אבל אמצעי, דאיכא אחרינא בתריה\u0004 \u0005[שיש אחר אחריו\u0006\u0005]\u0006 שהותר נדרו — \u0003משתרי\u0004 \u0005[הותר\u0006\u0005]\u0006 גם זה שאחריו. \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 כי כל \u0003חד בחבריה מתפיס\u0004 \u0005[אחד בחבירו נתפס\u0006\u0005].\u0006","ודוחים: \u0003לעולם אימא\u0004 \u0005[\u0006יכול אני לומר\u0005]\u0006 \u0003לך: בקמא מיתפסין\u0004 \u0005[בראשון נתפסים\u0006 כולם\u0005]\u0006 \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"אחרון\" דקתני\u0004 \u0005[ששנה\u0006\u0005]\u0006 שכולם אסורים חוץ ממנו — \u0003אמצעי,\u0004 ומי שאחריו אכן לא הותר, \u0003ו\u0004מדוע נקרא \"אחרון\" — \u0003איידי דתנא\u0004 \u0005[מתוך ששנה\u0006\u0005]\u0006 קודם לכן במשנה \u0003\"ראשון\", תנא\u0004 \u0005[שנה\u0006\u0005]\u0006 כאן לשון \u0003\"אחרון\",\u0004 אבל אין לדייק מכאן דבר.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005],\u0006 \u0003דתניא בהדיא\u0004 \u0005[ששנויה\u0006 ברייתא בפירוש\u0005]:\u0006 \u0003הותר הראשון —\u0004 \u0003הותרו כולן, הותר האחרון —\u0004 \u0003האחרון מותר וכולן אסורין, הותר אמצעי\u0004 — כל מי שהוא \u0003הימנו ולמטה\u0004 (אחריו) \u0003מותר, הימנו ולמעלה\u0004 (מלפניו) — \u0003אסור, שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 כי \u0003חד בחבריה מתפיס\u0004 \u0005[אחד בחברו נתפס\u0006\u0005].\u0006 ומסכמים, אכן \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 שכן הוא.","שנינו במשנה: מי שאמר \u0003\"הריני נזיר\" ושמע חבירו ואמר \"פי כפיו ושערי כשערו\" וכו'\u0004 — הרי הוא נזיר. ושואלים: \u0003משום\u0004 ש\u0003אמר \"פי כפיו ושערי כשערו\" הרי\u0004 הוא \u0003נזיר?\u0004"],["\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה לכך\u0005]\u0006 ממה ששנינו: אם אמר \u0003\"ידי נזירה\" ו\u0004כן אם אמר \u0003\"רגלי נזירה\" —\u0004 \u0003לא אמר כלום,\u0004 אבל אם אמר \u0003\"ראשי נזירה\"\u0004 או \u0003\"כבדי נזירה\" —\u0004 \u0003הרי זה נזיר. זה הכלל:\u0004 קיבל נזירות על \u0003דבר\u0004 (אבר, חלק מן הגוף) \u0003שהנשמה תלויה בו,\u0004 כלומר, שאי אפשר לחיות בלעדיו — \u0003הרי זה נזיר.\u0004 ואם קיבל נזירות על חלק בגוף שאפשר להתקיים אף בלעדיו — אינו נזיר. ואם כן אף האומר על שערו, שוודאי אין הנשמה תלויה בו — לא היה צריך להיות נזיר!","\u0003אמר רב יהודה:\u0004 יש להבין ש\u0003אמר הכי\u0004 \u0005[כך\u0006\u0005],\u0006 שכך היתה כוונתו: \u0003יעשה פי כפיו\u0004 להיאסר \u0003מיין, ושערי כשערו מלגוז.\u0004","שנינו במשנה אם אמרה אשה \u0003\"הריני נזירה\", ושמע בעלה ואמר \"ואני\" —\u0004 \u0003אינו יכול להפר\u0004 את נדרה. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: האם \u0003בעל\u0004 המפר את נדר אשתו \u0003מיעקר עקר\u0004 \u0005[עוקר\u0006\u0005]\u0006 את הנדר מעיקרו כאילו לא היה, \u0003או דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 הוא רק \u0003מיגז גייז\u0004 \u0005[גוזז\u0006 אותו\u0005],\u0006 כלומר, עוקר אותו מכאן ולהבא? ומסבירים: \u0003למאי נפקא מינה\u0004 \u0005[מה\u0006 הבדל דין יוצא מזה\u0005]\u0006 אם נאמר כצד זה או כצד זה —","\u0003לאשה שנדרה בנזיר\u0004 (נדר נזירות), \u0003ושמעה חברתה ואמרה \"ואני\", ושמע בעלה של ראשונה והפר לה.\u0004 ומעתה, \u0003אי אמרת מיעקר עקר\u0004 \u0005[אם אומר אתה שעוקר\u0006\u0005]\u0006 הבעל את הנדר מעיקרו — \u0003ההיא,\u0004 השניה, \u0003נמי אישתראי\u0004 \u0005[גם כן הותרה\u0006\u0005],\u0006 שהרי תלתה בנדר שמתברר כעת שלא היה קיים כלל. \u0003ואי אמרת מיגז גייז\u0004 \u0005[ואם אתה אומר\u0006 שהוא רק גוזז\u0005]\u0006 מכאן ולהבא — \u0003איהי אשתראי\u0004 \u0005[היא הותרה\u0006\u0005]\u0006 אבל \u0003חברתה אסירא\u0004 \u0005[חברתה\u0006 עדיין אסורה\u0005],\u0006 שהרי לא נעקר הנדר משעה שתלתה בו את נדרה. ואם כן \u0003מאי\u0004 \u0005[מה\u0006\u0005]\u0006 הפתרון לשאלה זו?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 ראיה לדבר ממה ששנינו: אמרה \u0003\"הריני נזירה\" ושמע בעלה ואמר \"ואני\" —\u0004 \u0003אינו יכול להפר. ואי סלקא דעתך בעל מיגז גייז\u0004 \u0005[ואם עולה על דעתך\u0006 שהבעל רק גוזז\u0005]\u0006 את הנדר — \u0003ליפר\u0004 \u0005[שיפר\u0006\u0005]\u0006 \u0003לאשתו והוא ליתסר\u0004 \u0005[ייאסר\u0006\u0005],\u0006 שהרי לנדרה היה חלות בשעה שתלה בו את נדרו, ולא נעקר למפרע מאותה שעה. \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן\u0006\u0005]\u0006 כי ה\u0003בעל מיעקר עקר\u0004 \u0005[עוקר\u0006\u0005]\u0006 את הנדר מעיקרו, וכיון שעל ידי כך נמצא שעוקר את נדרו שלו — אינו יכול להפר לה?","ודוחים: \u0003לא, לעולם\u0004 יכול אתה לומר שהבעל \u0003מיגז גייז\u0004 \u0005[גוזז\u0006\u0005]\u0006 את הנדר מכאן ולהבא. \u0003ו\u0004אם רק משום ענין זה, \u0003בדין הוא דליפר\u0004 \u0005[שיפר\u0006\u0005]\u0006 \u0003לה. והיינו טעמא דלא מצי מיפר\u0004 \u0005[ו\u0006אולם זה הטעם שאינו יכול להפר\u0005],\u0006 כי \u0003כיון\u0004 ש\u0003אמר לה \"ואני\"\u0004 הרי \u0003כמאן\u0004 \u0005[כמי\u0006\u0005]\u0006 ש\u0003אמר \"קיים ליכי\"\u0004 \u0005[לך\u0006\u0005]\u0006 \u0003דמי\u0004 \u0005[נחשב\u0006\u0005]\u0006 ובעל שקיים את נדר אשתו שוב אינו יכול להפירו. ולכן, \u0003אי מתשיל אהקמתו\u0004 \u0005[אם הוא נשאל\u0006 לחכם על הקמתו\u0005],\u0006 שמבקש שיתירו לו בית דין את מה שהקים — \u0003מצי מיפר\u0004 \u0005[יכול להפר\u0006\u0005],\u0006 \u0003ואי\u0004 \u0005[ואם\u0006\u0005]\u0006 \u0003לא —\u0004 \u0003לא מצי מיפר\u0004 \u0005[יכול להפר\u0006\u0005].\u0006 ואם כן אין מכאן ראיה.","ומציעים עוד ראיה: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 ראיה לדבר ממה ששנינו: \u0003האשה שנדרה בנזיר\u0004 (נדר נזירות), \u0003והפרישה את בהמתה\u0004 לקרבן הנזירות, \u0003ואחר כך הפר לה בעלה\u0004 את נדרה, ושוב אינה צריכה בהמה זו לקרבן, \u0003אם\u0004 מ\u0003שלו היתה הבהמה\u0004 ונתן לה לצורך הקרבן בלבד — הרי זה כאילו לא הוקדשה כלל, ו\u0003תצא ותרעה בעדר\u0004 עם שאר הבהמות, כבהמת חולין גמורה. \u0003ואם שלה היתה הבהמה,\u0004 זו המיועדת לקרבן \u0003החטאת —\u0004 \u0003תמות\u0004 כדין כל בהמת חטאת שאי אפשר להקריבה, שהיא מומתת.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006\u0005]\u0006 לומר שה\u0003בעל מיעקר עקר\u0004 \u0005[עוקר\u0006\u0005]\u0006 את הנדר מעיקרו — \u0003תיפוק\u0004 \u0005[תצא\u0006\u0005]\u0006 גם החטאת שהפרישה היא משלה \u0003לחולין,\u0004 כדין חטאת נזיר שהתירו חכמים את נדרו (להלן נזיר לא, ב)! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן\u0006\u0005]\u0006 כי ה\u0003בעל\u0004 רק \u0003מיגז גייז\u0004 \u0005[גוזז\u0006\u0005]\u0006 את הנדר, ובשעה שהפרישה בהמה היתה אכן נזירה, ולא נעקר דבר זה!","ודוחים: \u0003לעולם אימא\u0004 \u0005[\u0006יכול אני אומר\u0005]\u0006 \u0003לך\u0004 שה\u0003בעל מיעקר עקר\u0004 \u0005[עוקר\u0006\u0005]\u0006 את הנדר מעיקרו, \u0003והיינו טעמא\u0004 \u0005[וזה הטעם\u0006\u0005]:\u0006 \u0003כיון\u0004 ש\u0003לא צריכה כפרה\u0004 עוד, שהרי הנדר בטל מעתה, \u0003הות\u0004 \u0005[הריהי\u0006\u0005]\u0006 בהמה זו נדונה \u0003כ\u0004דין בהמת \u0003חטאת שמתו בעליה\u0004 שאין צורך עוד בכפרתה, \u0003וגמירי\u0004 \u0005[ולמודים אנו\u0006 במסורת\u0005]\u0006 ש\u0003חטאת שמתו בעליה\u0004 — \u0003תמות.\u0004","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 ראיה לדבר ממה ששנינו במשנה הבאה: \u0003האשה שנדרה בנזיר\u0004 (נדר נזירות), \u0003ו\u0004בכל זאת \u0003היתה שותה יין ומטמאה למתים —\u0004 \u0003הרי זו סופגת\u0004 (לוקה) \u0003את הארבעים\u0004 מלקות שלוקה בהם העובר על \"לאו\" מן התורה. ומעתה נברר, \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר\u0006\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר\u0006\u0005]\u0006 ש\u0003לא היפר לה\u0004 ה\u0003בעל\u0004 — וכי \u0003צריכא למימר\u0004 \u0005[צריך לומר\u0006\u0005]\u0006 שהיא לוקה? הרי כל נזיר שעובר על נזרו לוקה!","\u0003אלא פשיטא\u0004 \u0005[פשוט\u0006\u0005]\u0006 שמדובר כש\u0003היפר לה\u0004 ה\u0003בעל. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006\u0005]\u0006 לומר שה\u0003בעל מיעקר עקר\u0004 \u0005[עוקר\u0006\u0005]\u0006 את הנדר מעיקרו — \u0003אמאי\u0004 \u0005[מדוע\u0006\u0005]\u0006 \u0003סופגת ארבעים\u0004 מלקות? הלא היא כאילו לא נדרה כלל! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן\u0006\u0005]\u0006 שהבעל רק \u0003מיגז גייז\u0004 \u0005[גוזז\u0006\u0005]\u0006 את הנדר, ולכן כיון שחל עליה הנדר במשך זמן מסויים, הריהי לוקה על מה שעברה?","ודוחים: \u0003לעולם אימא\u0004 \u0005[\u0006יכול אני לומר\u0005]\u0006 \u0003לך\u0004 שה\u0003בעל מיעקר עקר\u0004 \u0005[עוקר\u0006\u0005]\u0006 את הנדר מעיקרו, \u0003ו\u0004אולם \u0003משום דקתני סיפא\u0004 \u0005[ששנה בסוף\u0006\u0005]:\u0006 \u0003היפר לה בעלה והיא לא ידעה, והיתה שותה יין ומטמאה למתים\u0004 — למרות שהיא התכוונה לעבירה, \u0003אינה סופגת את הארבעים\u0004 מלקות כיון שלא היתה כאן עבירה בפועל, משום כך"],["\u0003תנא נמי רישא\u0004 \u0005[שנה גם כן בתחילה\u0006\u0005]\u0006 \u0003סופגת,\u0004 אף על פי שאין בכך חידוש.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 ראיה ממקום אחר, ששנינו: \u0003האשה שנדרה בנזיר\u0004 (נדר נזירות) \u0003ונטמאת, ואחר כך הפר לה בעלה —\u0004 \u0003מביאה חטאת העוף, ואינה מביאה עולת העוף. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006\u0005]\u0006 לומר שה\u0003בעל\u0004 רק \u0003מיגז גייז\u0004 \u0005[גוזז\u0006\u0005]\u0006 את הנדר — \u0003תייתי נמי\u0004 \u0005[תביא גם כן\u0006\u0005]\u0006 \u0003עולת העוף\u0004 להשלים קרבן לכפר על מה שנטמאה בנזירותה! ואם כן מוכח מכאן שהבעל עוקר את הנדר מעיקרו, ולכן אינה מביאה עולת העוף.","את הראיה הזו דוחים: \u0003ואלא מאי\u0004 \u0005[מה\u0006\u0005]\u0006 אומר אתה שהבעל \u0003מיעקר עקר\u0004 \u0005[עוקר\u0006\u0005]\u0006 את הנדר מעיקרו? אם כן \u0003חטאת העוף נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003לא תייתי\u0004 \u0005[תביא\u0006\u0005]!\u0006 ומשיבים: אכן \u0003הכי נמי\u0004 \u0005[כך גם כן\u0006\u0005]\u0006 היה צריך להיות, \u0003ו\u0004אולם \u0003הא\u0004 \u0005[\u0006ברייתא זו\u0005]\u0006 כשיטת \u0003מני\u0004 \u0005[מי היא\u0006\u0005] —\u0006 \u0003ר' אלעזר הקפר היא.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 \u0003ר' אלעזר הקפר בר רבי אומר: מה תלמוד לומר\u0004 (מה בא ללמדנו) \u0003\"מאשר חטא על הנפש\"\u0004 (במדבר ו, יא), האמור בנזיר, שצריך להביא קרבן לכפר עליו? \u0003וכי באיזו נפש חטא זה\u0004 הנזיר? \u0003אלא מפני שציער עצמו\u0004 בכך שנמנע \u0003מן היין נקרא\u0004 על שום כך \u0003חוטא. והלא דברים קל וחומר: ומה זה שלא ציער עצמו אלא מן היין\u0004 בלבד \u0003נקרא חוטא, המצער עצמו\u0004 בנדרים וסיגופים \u0003מכל דבר —\u0004 \u0003על אחת כמה וכמה\u0004 שנקרא חוטא. ולשיטה זו ראוי לה שתביא את החטאת לכפר על עצם נזירותה, אף שהבעל בהפרתו עוקר את הנזירות מעיקרה.","ולאחר שניסינו לברר ממקורות שונים את השאלה אם בעל עוקר את הנדר מעיקרו או רק מכאן ולהבא, מציעים: \u0003תא שמע דתניא בהדיא\u0004 \u0005[בוא\u0006 ושמע ראיה לדבר ממה ששנינו בברייתא במפורש\u0005]\u0006 ועל ידה נפתרה בעיה זו: \u0003האשה שנדרה בנזיר\u0004 (נדר נזירות), \u0003ושמעה\u0004 זאת \u0003חבירתה ואמרה \"ואני\", ובא בעלה של ראשונה והפר לה —\u0004 \u0003היא מותרת וחבירתה אסורה. שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]:\u0006 שה\u0003בעל מיגז גייז\u0004 \u0005[גוזז\u0006\u0005]\u0006 את הנדר, אבל אינו עוקר אותו מעיקרו.","וממשיכה הברייתא, \u0003ר' שמעון אומר: אם אמרה לה\u0004 השניה לאחר ששמעה אותה מקבלת נזירות עליה \u0003\"הריני כמותיך\"\u0004 — במקרה כזה \u0003שתיהן מותרות,\u0004 שכיון שתלתה השניה את כל נזירותה בראשונה, ולא נדרה שום נדר משל עצמה, הרי משעה שבטלה נזירותה של הראשונה בטלה עמה גם נזירותה של השניה."],["\u0003מר זוטרא בריה\u0004 \u0005[בנו\u0006\u0005]\u0006 של \u0003רב מרי אמר: האי\u0004 \u0005[זו\u0006\u0005]\u0006 השאלה שאנו דנים בה עתה ביחס לאשה שהתפיסה נדרה באשה אחרת, מה יהא הדין אם הופר נדרה של הראשונה \u0003היינו\u0004 \u0005[זוהי\u0006\u0005]\u0006 ביסודה שאלתו של \u0003רמי בר חמא\u0004 בנושא אחר. \u0003דבעי\u0004 \u0005[ששאל\u0006\u0005]\u0006 \u0003רמי בר חמא:\u0004 אם אומר אדם על דבר מסויים: \u0003\"הרי\u0004 זה אסור \u0003עלי כבשר זבח שלמים\", מהו\u0004 הדין? האם יש כאן נדר האוסר את הדבר, או לא?","וצדדי השאלה: האם \u0003כי\u0004 \u0005[כאשר\u0006\u0005]\u0006 \u0003מתפיס איניש\u0004 \u0005[אדם\u0006\u0005]\u0006 בנדר, שאומר \"דבר זה יהא כמו זה\" \u0003בעיקרא\u0004 \u0005[בעיקרו\u0006\u0005]\u0006 הוא \u0003מתפיס.\u0004 ואף כאן, כיון שמתחילה, לפני זריקת הדם על המזבח, היה הבשר אסור בהנאה — נמצא שהתפיס בדבר שהוא אסור בהנאה והנדר חל. \u0003או דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003בצננא\u0004 \u0005[בצונן =\u0006 בהיתר\u0005]\u0006 \u0003מתפיס\u0004 את נדרו, והרי זבחי שלמים אחר זריקת הדם מותרים באכילה ואין הדבר נאסר עליו? ולכאורה שאלה זו דומה לשאלה בענין נדרה של האשה השניה, האם היא מתפיסה בעיקרו — תחילתו של הנדר הראשון — לפני שהופר, או בצד ההיתר שבו — לאחר מכן.","את ההצעה הזו דוחים: \u0003מי דמי\u0004 \u0005[האם דומים\u0006\u0005]\u0006 הדברים? \u0003התם\u0004 \u0005[שם\u0006\u0005]\u0006 \u0003כיון\u0004 ש\u0003אמר \"הרי עלי כבשר זבח שלמים\", אף על גב\u0004 \u0005[אף על פי\u0006\u0005]\u0006 ש\u0003לאחר שנזרק דמו מצי אכיל ליה\u0004 \u0005[יכול לאכול אותו\u0006\u0005]\u0006 \u0003בחוץ,\u0004 מכל מקום עדיין \u0003מיקדש קדיש\u0004 \u0005[קדוש\u0006\u0005]\u0006 הוא לעניינים שונים, ויש כאן נדר בדבר שיש בו איסור מסויים. \u0003אבל הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך\u0006\u0005]\u0006 לומר שמי שמתפיס — \u0003בצננא קא מתפיס\u0004 \u0005[בצונן,\u0006 בהיתר, הוא מתפיס\u0005]\u0006 \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003הפר לה בעלה\u0004 ואין כאן צד נדר כלל, ואין משמעות לדברים! \u0003איכא דאמרי\u0004 \u0005[ויש שאומרים\u0006\u0005]\u0006 שאין מקבלים את הדחיה הזו. ולדעתם, אכן \u0003היינו\u0004 \u0005[זו היא\u0006\u0005]\u0006 השאלה של \u0003רמי בר חמא ודאי.\u0004","ועוד שואלים: \u0003אמרה לה\u0004 לחבירתה שנדרה בנזיר, בנוסח \u0003\"הריני נזירה בעיקביך\"\u0004 ואחרי כן היפר בעלה של הראשונה את נדר אשתו, \u0003מהו\u0004 דינה של השניה? וצדדי השאלה: האם \u0003\"הריני בעיקביך\"\u0004 משמעותו \u0003בכולא מילתא\u0004 \u0005[בכל הדבר\u0006\u0005],\u0006 \u0003ו\u0004לכן \u0003שריא\u0004 \u0005[מותרת\u0006\u0005],\u0006 שהרי לבסוף הותרה אף הראשונה. \u0003או דלמא כמיקמי דליפר\u0004 \u0005[שמא כלפני שיפר\u0006\u0005]\u0006 \u0003לה בעלה\u0004 משמע, \u0003ו\u0004לכן \u0003אסירא\u0004 \u0005[אסורה\u0006\u0005]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 פתרון לשאלה ממה ששנינו: \u0003האשה\u0004 \u0003שנדרה בנזיר\u0004 (נדר נזירות) \u0003ושמע בעלה ואמר \"ואני\" —\u0004 \u0003אינו יכול להפר\u0004 שנמצא מיפר בכך את נדרו שלו, שהתפיס בשלה, ואינו יכול לעשות זאת. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006\u0005]\u0006 לומר \u0003כי אמר\u0004 \u0005[כאשר אומר\u0006\u0005]\u0006 \u0003לה \"הריני בעיקביך\"\u0004 — \u0003בעיקרא קא\u0004 \u0005[בעיקר\u0006 הנדר הריהו\u0005]\u0006 \u0003מתפיס\u0004 ואינו תולה את נדרו בנדרה לכל אורך הנזירות, אם כן \u0003ליפר\u0004 \u0005[שיפר\u0006\u0005]\u0006 \u0003לה לדידה ולוקים דידיה\u0004 \u0005[את שלה ויקים\u0006 את שלו\u0005],\u0006 כלומר, הוא ישאר באיסורו!","\u0003אלא לאו שמע מינה בכולא דמילתא\u0004 \u0005[האם לא תלמד מכאן\u0006 שבכל הדבר\u0005]\u0006 הוא \u0003מתפיס, והלכך\u0004 (ולכן) אפשר לדייק כך: דווקא \u0003הוא\u0004 ש\u0003לא מצי מיפר\u0004 \u0005[יכול להפר\u0006\u0005]\u0006 משום שאם יפר — נמצא כמיפר גם את נדרו שלו, \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003אשה\u0004 ש\u0003אמרה \"הריני בעיקביך\" היא נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003מותרת\u0004 בהפרת נדר הראשונה?","ודוחים: \u0003לא, לעולם\u0004 יכול אתה לומר כי \u0003בעיקרא\u0004 \u0005[בעיקרו\u0006\u0005]\u0006 של נדר הוא \u0003מתפיס, והכא\u0004 \u0005[וכאן\u0006\u0005],\u0006 בבעל, סיבה אחרת יש לכך שאינו יכול להפר, \u0003כיון דאמר\u0004 \u0005[שאומר\u0006\u0005]\u0006 \u0003לה \"ואני\" —\u0004 \u0003כאומר \"קיים ליכי\u0004 (לך) \u0003\"\u0004\u0003דמי\u0004 \u0005[נחשב\u0006\u0005],\u0006 שבקבלת הנדר הוא ממילא גם מקיים את נדרה. \u0003ו\u0004לכן, \u0003אי מתשיל אהקמתו\u0004 \u0005[אם\u0006 הוא נשאל לחכם על הקמתו\u0005],\u0006 שרוצה להתחרט על שהקים את נדרה — \u0003מצי מיפר\u0004 \u0005[יכול להפר\u0006\u0005],\u0006 \u0003ואי\u0004 \u0005[ואם\u0006\u0005]\u0006 \u0003לא\u0004 נשאל — \u0003לא.\u0004","שנינו במשנה: אמר הבעל \u0003\"הריני נזיר ואת\" ואמרה\u0004 אשתו אחריו \u0003\"אמן\" —\u0004 \u0003מיפר את שלה, ושלו קיים. ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא: מי שאמר לאשתו \u0003\"הריני נזיר ואת\", ואמרה \"אמן\" —\u0004 \u0003שניהם אסורין, ואם לאו\u0004 \u0005[לא\u0006\u0005],\u0006 שלא ענתה \"אמן\" — \u0003שניהם מותרין, מפני שתלה\u0004 את \u0003נדרו בנדרה,\u0004 שהתכוון לומר: הריני נזיר אם את תהיי נזירה, ואם היא לא קיבלה על עצמה — אף נדרו בטל. הרי שלפי הברייתא אינו יכול להפר את נדרה אם אמרה \"אמן\", והרי זה שלא כמשנתנו.","\u0003אמר רב יהודה: תני\u0004 \u0005[שנה\u0006\u0005],\u0006 תקן את הנוסח בברייתא כך: \u0003\"מיפר את שלה ושלו קיים\"\u0004 כמשנתנו, ולא בנוסח \"שניהם אסורים\". \u0003אביי אמר: אפילו תימא כדקתני\u0004 \u0005[תאמר כפי ששנויה\u0006\u0005]\u0006 הברייתא, ועדיין יש לומר שיש הבדל בדרך שבה נאמרו הדברים; ב\u0003ברייתא\u0004 מדובר \u0003כגון דקאמר\u0004 \u0005[שאומר\u0006\u0005]\u0006 \u0003לה\u0004 משפט שלם אחד: \u0003\"הריני נזיר ואת\" דקא תלי\u0004 \u0005[שתולה\u0006\u0005]\u0006 את \u0003נדרו בנדרה,\u0004 ומשום כך אם היא אינה נזירה — אף נדרו בטל."],["\u0003ומתניתין\u0004 \u0005[ומשנתנו\u0006\u0005]\u0006 מדברת \u0003כגון דאמר\u0004 \u0005[שאומר\u0006\u0005]\u0006 \u0003לה\u0004 בלשון שאלה \u0003\"הריני נזיר ואת מאי\"\u0004 \u0005[מה\u0006\u0005]?\u0006 ומדבריו משמע שהוא מקבל על עצמו נזירות גמורה, אלא ששואל אם גם אשתו רוצה להצטרף אליו. \u0003משום הכי\u0004 \u0005[כך\u0006\u0005],\u0006 מתוך שאין נדרו תלוי בנדרה, ואין הפרת נדרה גוררת הפרת נדרו — \u0003מיפר את שלה ושלו קיים.\u0004","\u0003האשה שנדרה בנזיר\u0004 (נדר נזירות), ועברה על נדרה, \u0003והיתה שותה ביין ומטמאה למתים —\u0004 \u0003הרי זו סופגת\u0004 (לוקה) \u0003את הארבעים\u0004 מלקות על כל אחת ממצוות לא תעשה מן התורה שעברה עליהן. \u0003הפר לה בעלה, והיא לא ידעה שהפר לה בעלה, והיתה שותה ביין ומטמאה למתים —\u0004 \u0003אינה סופגת את הארבעים\u0004 שהרי משהיפר לה שוב אינה נזירה. \u0003ר' יהודה אומר: אם אינה סופגת את הארבעים\u0004 מלקות מן התורה — \u0003תספוג מכת מרדות\u0004 (מלקות מדברי סופרים), כדי להענישה על שנתכוונה לעבור עבירה במזיד. שהרי למרות שהיה מותר לה לשתות יין, היא לא ידעה על כך ובכל זאת שתתה יין.","בקשר לאמור במשנה מביאים עוד את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]\u0006 על האמור בתורה בפרשת נדרים: \u0003\"אישה הפרם וה' יסלח לה\"\u0004 (במדבר ל, יג) — \u0003באשה שהפר לה בעלה\u0004 את נדרה \u0003והיא לא ידעה\u0004 שהיפר לה, והתכוונה לעבור עליו במזיד \u0003הכתוב מדבר, שהיא צריכה כפרה וסליחה\u0004 אם עשתה מה שאסרה עליה בנדרה.","\u0003וכשהיה מגיע ר' עקיבא אצל פסוק זה היה בוכה,\u0004 ואומר: \u0003ומה מי שנתכוון לעלות בידו\u0004 (לקחת) ולאכול \u0003בשר חזיר,\u0004 שנתכוון לעשות איסור, \u0003ועלה בידו\u0004 ואכל \u0003בשר טלה,\u0004 שבפועל לא עשה איסור, כאשה זו שלא ידעה שהיפר לה בעלה, שבפועל לא חטאה אבל התכוונה לאיסור — בכל זאת הוא \u0003טעון\u0004 (צריך) \u0003כפרה וסליחה, המתכוון לעלות בידו בשר חזיר ועלה בידו\u0004 בפועל \u0003בשר חזיר —\u0004 \u0003על אחת כמה וכמה\u0004 שהוא טעון כפרה.","\u0003כיוצא בדבר\u0004 לגבי כפרתו של מי שנתכוון לעבירה \u0003אתה אומר:\u0004 נאמר בקשר להבאת קרבן אשם תלוי (הבא על ספק עבירה) \u0003\"ולא ידע ואשם ונשא עונו\"\u0004 (ויקרא ה, יז) ואף מכאן יש ללמוד:","\u0003ומה מי שנתכוון לעלות בידו בשר טלה\u0004 שמותר באכילה, \u0003ועלה בידו בשר חזיר,\u0004 שעשה איסור שלא בכוונה, \u0003כגון\u0004 שלקח \u0003חתיכה\u0004 שהיא \u0003ספק של שומן\u0004 המותר באכילה, \u0003ספק של חלב\u0004 האסור באכילה, ואכלה, שעליה חייב להביא אשם תלוי — עליו \u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 \u0003\"ונשא עונו\",\u0004 שמוטל עליו חטא ועליו לכפרו בקרבן, \u0003מי שנתכוון לעלות בידו בשר חזיר, ועלה בידו בשר חזיר —\u0004 \u0003על אחת כמה וכמה\u0004 שצריך כפרה.","\u0003איסי בן יהודה אומר:\u0004 יש לפרש פסוק זה \u0003\"ולא ידע ואשם ונשא עונו\"\u0004 באופן שונה: \u0003ומה מי שנתכוון לעלות בידו בשר טלה ועלה בידו בשר חזיר, כגון\u0004 שהיו לפניו \u0003שתי חתיכות אחת של חלב ואחת של שומן,\u0004 ולא ידע איזו מהן האסורה ולקח ואכל אחת מהן — עליו נאמר \u0003\"ונשא עונו\",\u0004 שמוטל עליו העוון ועליו לכפרו בקרבן אשם, \u0003המתכוון לעלות בידו בשר חזיר ועלה בידו בשר חזיר על אחת כמה וכמה\u0004 שצריך כפרה!","ומעירים: \u0003על דבר זה ידוו\u0004 (יצטערו) \u0003הדווים,\u0004 שהרי, נלמד מכאן כמה צריך אדם לסליחה וכפרה.","ושואלים: \u0003וכל הני\u0004 \u0005[אלה\u0006\u0005]\u0006 \u0003למה לי?\u0004 מדוע הוצרך להביא כמה דוגמאות לאותו רעיון עצמו? ומשיבים: \u0003צריכין\u0004 \u0005[צריכים\u0006\u0005]\u0006 את כולם, \u0003דאי תנא\u0004 \u0005[שאם היה שונה\u0006\u0005]\u0006 רק \u0003לגבי אשה\u0004 שנדרה, היינו אומרים \u0003התם\u0004 \u0005[שם\u0006\u0005]\u0006 \u0003הוא דבעיא\u0004 \u0005[שצריכה\u0006\u0005]\u0006 \u0003כפרה וסליחה —\u0004 \u0003משום דמעיקרא לאיסורא איכוון\u0004 \u0005[שמתחילה לאיסור התכוונה\u0006\u0005],\u0006 \u0003אבל\u0004 מי שלקח \u0003חתיכה ספק של חלב ספק של שומן, דלהיתרא איכוין\u0004 \u0005[שלהיתר התכוון\u0006\u0005],\u0006 הייתי אומר ש\u0003לא בעי\u0004 \u0005[צריך\u0006\u0005]\u0006 \u0003כפרה וסליחה.\u0004","\u0003ואי איתמר הדא\u0004 \u0005[ואם היתה נאמרת\u0006 רק זו\u0005]\u0006 באוכל חתיכה שהיא ספק חלב, \u0003דאיכא איסורא\u0004 \u0005[שיש\u0006 על כל פנים איסור לפניו\u0005],\u0006 שהרי יתכן שאכל איסור ממש, הייתי אומר כי דווקא זה צריך כפרה, \u0003אבל אשה\u0004 ש\u0003הפר לה בעלה דהתירא\u0004 \u0005[ש\u0006היה זה היתר\u0005]\u0006 בפועל — \u0003לא תיבעי\u0004 \u0005[תצטרך\u0006\u0005]\u0006 \u0003כפרה וסליחה.\u0004","\u0003ואי איתמר הני תרתי\u0004 \u0005[ואם היו נאמרים\u0006 רק אלו השתים\u0005],\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר\u0006\u0005]:\u0006 \u0003הני תרתי\u0004 \u0005[אלה השתים\u0006\u0005]\u0006 \u0003הוא דסגי להון\u0004 \u0005[שדי להן\u0006\u0005]\u0006 \u0003בכפרה וסליחה,\u0004 כיון \u0003שלא איקבע איסורא\u0004 \u0005[נקבע האיסור\u0006\u0005],\u0006 שאף במקרה שאכל חתיכה שהיא ספק חלב לא היה ברור שיש איסור באותו דבר, \u0003אבל\u0004 אם היו לפניו \u0003שתי חתיכות אחת של חלב ואחת של שומן, דאיקבע איסורא\u0004 \u0005[שנקבע האיסור\u0006\u0005],\u0006 שהיה ברור לו שיש חתיכה של איסור גמור לפניו, ובכל זאת אכל אחת מהן, יכול הייתי לומר ש\u0003לא סגי ליה\u0004 \u0005[די לו\u0006\u0005]\u0006 \u0003בכפרה וסליחה,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 איסי בן יהודה ש\u0003לא שנא\u0004 \u0005[שונה\u0006\u0005],\u0006 ואף הוא בכלל \"ונשא עוונו... וכפר עליו הכהן... ונסלח לו\" (ויקרא ה, יז-יח).","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: מאי דכתיב\u0004 \u0005[מהו שנאמר\u0006\u0005]\u0006 \u0003\"כי ישרים דרכי ה' וצדקים ילכו בם ופשעים יכשלו בם\"\u0004 (הושע יד, י), כיצד אותה דרך יש בה צדדים לכאן לכאן? — \u0003משל לשני בני אדם שצלו את\u0004 קרבן \u0003פסחיהן\u0004 כדין, בערב פסח, \u0003אחד\u0004 מהם \u0003אכלו לשום\u0004 (לשם) \u0003מצוה, ואחד אכלו לשום אכילה גסה\u0004 שאוכל בדוחק ובאונס, \u0003זה שאכלו לשום מצוה\u0004 — נתקיים בו \u0003\"וצדקים ילכו בם\", וזה שאכלו לשום אכילה גסה — נתקיים בו\u0004","\u0003\"ופשעים יכשלו בם\". אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003ריש לקיש: האי\u0004 \u0005[זה\u0006\u0005]\u0006 \u0003\"רשע\" קרית ליה\u0004 \u0005[אתה קורא לו\u0006\u0005]?!\u0006 \u0003נהי\u0004 \u0005[אם אמנם\u0006\u0005]\u0006 ש\u0003לא קא עביד\u0004 \u0005[אינו עושה\u0006\u0005]\u0006 \u0003מצוה מן המובחר\u0004 באכילת פסח זה, \u0003פסח מיהא קא עביד\u0004 \u0005[בכל זאת עושה\u0006\u0005]\u0006 ומצוה היא! \u0003אלא\u0004 כך צריך לומר: \u0003משל לשני בני אדם, זה אשתו ואחותו עמו\u0004 בבית, \u0003וזה אשתו ואחותו עמו\u0004 וכל אחד מהם בא לביתו ובא על אחת מהן ולא ראה מי היא, \u0003לזה נזדמנה לו אשתו ולזה נזדמנה לו אחותו. זה שנזדמנה לו אשתו — נתקיים בו הכתוב\u0004 \u0003\"צדקים ילכו בם\", וזה שנזדמנה לו אחותו —\u0004 \u0003\"ופשעים יכשלו בם\".\u0004","ומקשים: \u0003מי דמי\u0004 \u0005[האם דומים\u0006\u0005]\u0006 הדברים? \u0003אנן קאמרינן חדא דרך\u0004 \u0005[אנו אמרנו דרך אחת\u0006\u0005],\u0006 ששני אנשים עושים אותו מעשה, שמהלכים באותה דרך עצמה, ועם כל זה אחד מצליח בה והשני נכשל בה. אולם \u0003הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 הלא \u0003שתי דרכים\u0004 הן, שהרי כל אחד מהם עשה מעשה אחר, זה בא על אשתו, וזה — על אחותו, ואין להשוות ביניהם. \u0003אלא משל ללוט ושתי בנותיו עמו. הן שנתכוונו\u0004 בביאה זו \u0003לשם מצוה,\u0004 שחשבו שכל העולם נשמד, ורצו לקיים את המין האנושי — עליהן נאמר \u0003\"וצדקים ילכו בם\", הוא שנתכוין לשם עבירה\u0004 — עליו נאמר \u0003\"ופשעים יכשלו בם\".\u0004","ושואלים: \u0003ודלמא\u0004 \u0005[ושמא\u0006\u0005]\u0006 \u0003הוא,\u0004 לוט, \u0003נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003לשום\u0004 (לשם) \u0003מצוה איכוון\u0004 \u0005[התכוון\u0006\u0005]\u0006 בכך? ומשיבים: אי אפשר לומר כן, שהרי בקשר ללוט כבר \u0003אמר ר' יוחנן: כל הפסוק הזה\u0004 \"וישא לוט את עיניו וירא את כל ככר הירדן כי כולה משקה\" (בראשית יג, י) \u0003על שם עבירה\u0004 של זנות \u0003נאמר,\u0004 ומכאן למדים שלוט עצמו היה בעל תאווה ומן הסתם התכוון לעבירה.","וכך נרמזים הדברים: \u0003\"וישא לוט\"\u0004 (בראשית יג, י) הריהו רמז לאותה לשון האמורה בנסיונו של יוסף \u0003\"ותשא אשת אדניו את עיניה\"\u0004 (בראשית לט, ז) שהיא נשיאת עינים בעבירה. נאמר בלוט: \u0003[\"את עיניו\"]\u0004 — אותה לשון כמו \u0003\"כי היא ישרה בעיני\"\u0004 (שופטים יד, ג), שאמר שמשון כשרצה לשאת בת פלשתים.","\u0003\"וירא\"\u0004 האמור בלוט הריהו כלשון האמורה בדינה בת יעקב \u0003\"וירא אתה שכם בן חמור...\u0004 וישכב אותה\u0003\"\u0004 (בראשית לד, ב). נאמר בלוט \u0003\"את כל ככר הירדן\",\u0004 והוא כמו הלשון \u0003\"כי בעד אשה זונה עד ככר לחם\"\u0004 (משלי ו, כו). נאמר בלוט \u0003\"כי כלה משקה\"\u0004 — בדומה למה שנאמר \u0003\"אלכה אחרי מאהבי נתני לחמי ומימי צמרי ופשתי שמני ושקויי\"\u0004 (הושע ב, ז).","ושואלים: \u0003והא מינס אניס\u0004 \u0005[והרי אנוס היה\u0006\u0005]\u0006 לוט, שהרי בשנתו אירע הדבר! ומשיבים: \u0003תנא\u0004 \u0005[שנה\u0006\u0005]\u0006 החכם \u0003משום\u0004 (בשם) \u0003ר' יוסי בר רב חוני: למה נקוד\u0004 בתורה \u0003על\u0004 האות \u0003וי\"ו\u0004 של \u0003\"ובקומה\" של בכירה\u0004 שנאמר \"ולא ידע (לוט) בשכבה ובקומה\" (בראשית יט, לג) ויש נקודה על הוא\"ו, \u0003לומר: שבשכבה\u0004 אמנם \u0003לא ידע, אבל בקומה ידע\u0004 מה שעשה, שלאחר זמן הבין מה קרה.","ושואלים: \u0003ומאי הוה ליה למיעבד\u0004 \u0005[ומה היה לו לעשות\u0006\u0005]\u0006 בענין זה? \u0003מאי דהוה הוה\u0004 \u0005[מה שהיה היה\u0006\u0005]!\u0006 ומשיבים: \u0003נפקא מינה, דלפניא אחרינא\u0004 \u0005[יוצא מזה שבערב האחר,\u0006 הבא\u0005],\u0006 \u0003לא איבעי למישתי חמרא\u0004 \u0005[היה צריך\u0006 שוב לשתות יין\u0005],\u0006 ואם שתה גם בערב השני ומתוך כך בא למעשה שעשה בבתו הצעירה, משמע שרצה בדבר.","ועוד בקשר ללוט \u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר\u0006\u0005]\u0006 \u0003\"אח נפשע מקרית עז\u0004"],["\u0003ומדינים כבריח ארמון\"\u0004 (משלי יח, יט)? \u0003\"אח נפשע מקרית עז\" זה לוט\u0004 שנקרא אחי אברהם (\"וישמע אברהם כי נשבה אחיו\". בראשית יד, יד ועוד) \u0003שפירש מאברהם, \"ומדינים כבריח ארמון\" שהטיל מדינים\u0004 (=מדנים, מריבה) בין ישראל לבני לוט \u0003כבריחין וארמון,\u0004 כבריחים שנועלים דלתות ארמון ואין יכולים הנמצאים בחוץ להיכנס פנימה, וכך נאסרו בני עמון ומואב שהם בני לוט מלבוא בקהל ישראל. והוא שנאמר \u0003\"לא יבא עמוני ומואבי בקהל ה'\"\u0004 (דברים כג, ד).","ובאותו ענין \u0003דרש רבא ואיתימא\u0004 \u0005[ויש אומרים\u0006 שדרש זאת\u0005]\u0006 \u0003ר' יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר\u0006\u0005]\u0006 \u0003\"לתאוה יבקש נפרד בכל תושיה יתגלע\"\u0004 (משלי יח, א)? \u0003\"לתאוה יבקש נפרד\" —\u0004 \u0003זה לוט\u0004 שנפרד מאברהם, \u0003\"ובכל תושיה יתגלע\" —\u0004 \u0003שנתגלה\u0004 לבסוף \u0003קלונו בבתי כנסיות\u0004 שקוראים בהם בתורה על מעשיו, \u0003ובבתי מדרשות,\u0004 ששונים בהם את דין צאצאיו. \u0003דתנן\u0004 \u0005[ש\u0006כן שנינו במשנה\u0005]:\u0006 \u0003עמוני ומואבי אסורין\u0004 לבוא בקהל לשאת אשה מישראל, \u0003ואיסורן איסור עולם.\u0004","אגב הדברים האמורים בבנות לוט שעשו זנות מתוך כוונה של מצוה, מביאים מה ש\u0003אמר עולא: תמר זינתה,\u0004 שבא עליה יהודה חמיה כזונה (ראה בראשית פרק לח), וגם \u0003זמרי\u0004 בן סלוא \u0003זינה\u0004 עם המדיינית (ראה במדבר פרק כה) ולכאורה מעשיהם שווים, אלא","\u0003תמר\u0004 ש\u0003זינתה\u0004 לשם מצוה, להעמיד זרע — \u0003יצאו ממנה מלכים\u0004 מלכי בית דוד, שבאו מפרץ בנה (ראה רות ד, יח-כב) \u0003ונביאים\u0004 כגון ישעיהו. ואילו \u0003זמרי\u0004 ש\u0003זינה\u0004 לעבירה — \u0003נפלו עליו\u0004 (בגללו) \u0003כמה רבבות מישראל,\u0004 עשרים וארבעה אלף במגיפה (במדבר כה, ט). ללמד שהכל תלוי בכוונה.","\u0003אמר רב נחמן בר יצחק: גדולה עבירה לשמה,\u0004 כלומר, עבירה שנעשית לשם שמים, \u0003ממצוה\u0004 שנעשית \u0003שלא לשמה.\u0004 ומקשים: האם יש לדמות מצוה שלא לשמה לעבירה? \u0003והאמר\u0004 \u0005[והרי אמר\u0006\u0005]\u0006 \u0003רב יהודה אמר רב: לעולם יעסוק אדם בתורה ובמצות אפילו שלא לשמן, שמתוך שלא לשמן בא לשמן,\u0004 ואיך אפשר לומר שעבירה לשמה גדולה יותר?","\u0003אלא\u0004 תקן הלשון וכך \u0003אימא\u0004 \u0005[תאמר\u0006\u0005]:\u0006 עבירה לשמה היא \u0003כמצוה שלא לשמה.\u0004 וראיה לדבר ממה \u0003דכתיב\u0004 \u0005[שנאמר\u0006\u0005]:\u0006 \u0003\"תברך מנשים יעל אשת חבר הקיני מנשים באהל תברך\"\u0004 (שופטים ה, כד). ופירשו: \u0003מאן\u0004 \u0005[מי\u0006 הן\u0005]\u0006 אלו ה\u0003נשים שבאהל —\u0004 \u0003שרה רבקה רחל ולאה,\u0004 ללמד שביאה זו של עבירה שנבעלה יעל לסיסרא לשם שמים, על מנת להרוג אותו בסופו של דבר, היא כמו הביאות שעשו האמהות. ומנין לנו שאכן עברה יעל אותה עבירה?","ש\u0003אמר ר' יוחנן: שבע בעילות בעל אותו רשע\u0004 (סיסרא) את יעל \u0003באותה שעה, שנאמר: \"בין רגליה כרע נפל שכב\u0004 בין רגליה כרע נפל באשר כרע שם נפל שדוד","\u0003\"\u0004(שופטים ה, כז) שבכל פעם שנאמר בפסוק זה \"כרע\" או \"נפל\" או \"שכב\" רמז הוא לביאה נוספת שבא עליה. ושואלים: \u0003והא קא מתהניא\u0004 \u0005[והרי נהנתה\u0006\u0005]\u0006 על כל פנים כמי שעשתה רק לשם שמים \u0003מבעילה דיליה\u0004 \u0005[שלו\u0006\u0005]\u0006 ולמה משבחה הכתוב? \u0003אמר ר' יוחנן: כל טובתן של רשעים,\u0004 כלומר, דבר טובה שעושים רשעים — \u0003אינה אלא רעה אצל צדיקים,\u0004 ובוודאי שלא נהנתה מדבר זה. ומנין אנו למדים זאת?","\u0003שנאמר\u0004 ללבן הארמי כאשר רדף אחרי יעקב: \u0003\"השמר לך מדבר עם יעקב מטוב עד רע\"\u0004 (בראשית לא, כד), ויש לשאול: \u0003בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 לדבר \u0003רע\u0004 — \u0003שפיר\u0004 \u0005[יפה\u0006\u0005]\u0006 ומובן מדוע נצטווה שלא ידבר אתו, \u0003אלא טוב אמאי\u0004 \u0005[מדוע\u0006\u0005]\u0006 \u0003לא\u0004 ידבר אתו? \u0003אלא, לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן\u0006\u0005]\u0006 שאפילו \u0003טובתו\u0004 של לבן \u0003רעה היא\u0004 בעיני יעקב. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 שכן הוא.","\u0003גופא\u0004 \u0005[לגופה\u0006\u0005]\u0006 של המימרה שנאמרה קודם בקיצור, מביאים \u0003אמר רב יהודה אמר רב: לעולם יעסוק אדם בתורה ובמצות אפילו שלא לשמן, שמתוך שלא לשמן בא לשמן.\u0004 וראיה לדבר — \u0003שבשכר ארבעים ושנים קרבנות שהקריב בלק הרשע,\u0004 שלא עשה לשם שמים אלא כדי לקלל את ישראל — מכל מקום \u0003זכה ויצאה ממנו רות\u0004 שנתגיירה לשם שמים, ואף יצא ממנה דוד מלך ישראל. \u0003ו\u0004כיוצא בדבר \u0003אמר ר' יוסי בר' חנינא: רות, בת בנו של עגלון מלך מואב היתה,\u0004 והוא היה מבניו של בלק מלך מואב.","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: מנין שאין הקדוש ברוך הוא מקפח אפילו שכר שיחה נאה,\u0004 כלומר, שאפילו על אמירת דברים בלשון נקיה מקבל אדם שכר על כך, ש\u0003אילו\u0004 הבת ה\u0003בכירה\u0004 של לוט \u0003דקריתיה\u0004 \u0005[שקראה לו\u0006 לבנה\u0005]\u0006 \u0003מואב,\u0004 שבשמו נרמז במפורש שנולד לה מן האב \u0003אמר ליה רחמנא\u0004 \u0005[אמרה לו התורה\u0006\u0005]\u0006 למשה \u0003\"אל תצר את מואב ואל תתגר בם מלחמה\"\u0004 (דברים ב, ט) ונדייק: \u0003מלחמה הוא\u0004 ש\u0003לא\u0004 הותרה, \u0003אבל צעורי צערינן\u0004 \u0005[לצער,\u0006 מותר לנו לצער אותם\u0005],\u0006","\u0003ואילו\u0004 הבת ה\u0003צעירה דקריתיה\u0004 \u0005[שקראה לו\u0006 לבנה\u0005]\u0006 \u0003בן עמי,\u0004 שרמזה שהוא בן המשפחה, ולא אמרה במפורש שהוא בן אביה על זרעה. \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 למשה: \u0003\"אל תצרם ואל תתגר בם\"\u0004 (דברים ב, יט) לומר: \u0003אפילו צעורי\u0004 \u0005[לצער\u0006\u0005],\u0006 \u0003לא תצערינן\u0004 \u0005[תצערם\u0006\u0005]\u0006 \u0003כלל.\u0004","\u0003אמר ר' חייא בר אבין אמר ר' יהושע בן קרחה: לעולם יקדים אדם לדבר מצוה, ש\u0004כן \u0003בשכר לילה אחת שקדמתה\u0004 הבת ה\u0003בכירה לצעירה\u0004 וכוונתה היתה למצוה"],["\u0003זכתה וקדמה ארבעה דורות בישראל למלכות,\u0004 שהיו מצאצאי רות המואביה בישראל ארבעה דורות (עובד, ישי, דוד, שלמה) לפני רחבעם בן שלמה, שהיה בנה של נעמה העמונית.","\u0003האשה שנדרה בנזיר\u0004 (נדר נזירות), \u0003והפרישה את בהמתה\u0004 (בהמות שונות) לצורך קרבן טהרה של נזיר, לכשתשלים את נזירותה כדין, \u0003ואחר כך היפר לה בעלה\u0004 את נדרה ונמצא שאין היא נזירה כלל ואינה מביאה קרבנות נזיר, מה דינם של הבהמות הללו? \u0003אם שלו,\u0004 של הבעל, \u0003היתה הבהמה —\u0004 \u0003תצא ותרעה בעדר\u0004 כחולין גמורים.","\u0003ואם שלה היתה הבהמה,\u0004 כיון שיש קרבנות שונים, זו שהפרישה לשם \u0003החטאת —\u0004 \u0003תמות,\u0004 שגורמים לה למות בכך שמכניסים אותה למקום סגור, ומונעים ממנה אכילה ושתיה. כפי שיבואר טעמו של דבר בגמרא. \u0003ו\u0004הבהמה שהופרשה ל\u0003עולה —\u0004 \u0003תקרב\u0004 למזבח כ\u0003עולה,\u0004 שהרי היא יכולה להביא אותה בכל אופן כקרבן נדבה. והבהמה שהופרשה ל\u0003שלמים —\u0004 \u0003תקרב שלמים\u0004 כנדבה, \u0003ו\u0004קרבנות שלמים אלה \u0003נאכלין ליום אחד\u0004 בלבד, ולא יותר, כדין שלמי הנזיר (אף כי שלמי נדבה רגילים נאכלים לשני ימים) \u0003ואינן טעונין\u0004 קרבן \u0003לחם\u0004 (חלות ורקיקים), כשם שטעונים קרבנות הנזיר.","\u0003היו לה מעות סתומין,\u0004 כלומר, אם הפרישה כסף לכל קרבנותיה, אבל לא קבעה איזה מן הכסף ילך לצורך איזה קרבן — \u0003יפלו\u0004 כל הכספים \u0003לנדבה\u0004 לשם הקרבת עולות למזבח. היו \u0003מעות מפורשין,\u0004 שחילקה את הכסף וקבעה שמעות מסויימות תהיינה עבור החטאת ואחרות לעולה וכו', אף שעדיין לא קנתה בהן בהמות, כבתחילת המשנה, \u0003דמי\u0004 ה\u0003חטאת —\u0004 \u0003ילכו לים המלח,\u0004 שמאבדים אותם מן העולם, כגון בזריקה לים. \u0003לא נהנין\u0004 מהם — משום שיש בהם צד קדושה, אבל גם \u0003לא מועלין בהן,\u0004 שאם נהנה אדם מהם — אינו מביא קרבן מעילה כאדם שנהנה מן הקודש.","\u0003דמי עולה —\u0004 \u0003יביאו\u0004 מהם \u0003עולה, ומועלין בהן,\u0004 שהרי הם ראויים להיות קרבן נדבה וחלה קדושה עליהם, וכיוצא בזה \u0003דמי שלמים —\u0004 \u0003יביאו\u0004 מהם \u0003שלמים, ונאכלין ליום אחד,\u0004 כדין שלמי נזיר, \u0003ואין טעונין לחם.\u0004","בבירור שיטת משנתנו שואלים: \u0003מאן\u0004 \u0005[מיהו\u0006\u0005]\u0006 ה\u0003תנא\u0004 הסבור שה\u0003בעל לא משתעבד לה\u0004 לאשתו לתת מרכושו קרבנות שהיא חייבת בהם, ולכן נאמר במשנה שאם האשה הפרישה בהמה שלו לקרבנותיה — לא חלה עליה קדושה? \u0003אמר רב חסדא:\u0004 שיטת \u0003רבנן\u0004 \u0005[חכמים\u0006\u0005]\u0006 \u0003היא. דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך\u0006\u0005]\u0006 לומר ששיטת \u0003ר' יהודה היא, אמאי\u0004 \u0005[מדוע\u0006\u0005]\u0006 אם הפרישה בהמות משל בעלה \u0003תצא\u0004 הבהמה לחולין \u0003ותרעה בעדר? הא\u0004 \u0005[הרי\u0006\u0005]\u0006 הבעל \u0003משתעבד לה\u0004 לאשתו להביא גם קרבנות עבורה, ונמצא שהקדשה — אפילו משלו — היה הקדש גמור.","ומסבירים מה ענין מחלוקת זו של חכמים ור' יהודה — \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: אדם מביא קרבן עשיר על אשתו.\u0004 שאם נתחייבה אשתו בקרבן (כגון קרבן היולדת, שיש חילוק בקרבנותיה אם היא עשירה או עניה), אף על פי שמצד רכושה שלה אין לה אלא כדי קרבן עני, אם הוא עשיר — הרי הוא מביא קרבן עשיר עבורה.","\u0003וכן\u0004 מביא \u0003כל קרבנותיה שהיא חייבת,\u0004 ואף אם נתחייבה בהם קודם לנישואיה, \u0003שכך כתב לה\u0004 בכתובתה: \u0003\"כל אחריות דאית ליך\u0004 \u0005[שיש לך\u0006\u0005]\u0006 \u0003עלי מן קדמת דנא\u0004 \u0005[מקודם\u0006\u0005],\u0006 אני מקבל על עצמי\u0003\".\u0004 ואף קרבנות אלה בכלל האחריות הם.","\u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר\u0006\u0005]\u0006 שמשנתנו כשיטת \u0003ר' יהודה,\u0004 מכל מקום אין הבעל משועבד במקרה שהיפר לה, שכן \u0003כי משעבד\u0004 \u0005[כאשר\u0006 הוא משועבד\u0005]\u0006 \u0003לה\u0004 להביא קרבנותיה — הרי זה דווקא \u0003במילתא דצריכא\u0004 \u0005[בדבר שצריך\u0006\u0005]\u0006 \u0003לה,\u0004 אבל \u0003במילתא\u0004 \u0005[בדבר\u0006\u0005]\u0006 ש\u0003לא צריכא\u0004 \u0005[צריך\u0006\u0005]\u0006 \u0003לה —\u0004 \u0003לא.\u0004 ואף כאן, כיון שביטל את נדר הנזירות שלה — ממילא שוב אינה צריכה עוד לקרבן זה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים\u0006\u0005]\u0006 שמועה זו בלשון אחרת: \u0003מאן\u0004 \u0005[מיהו\u0006\u0005]\u0006 ה\u0003תנא\u0004 של משנתנו זו, שדווקא אם היפר לאשתו שוב אינו משועבד לה? \u0003אמר רב חסדא: ר' יהודה היא, ו\u0004טעמו: \u0003כי משעבד\u0004 \u0005[כאשר\u0006 הבעל משועבד\u0005]\u0006 \u0003לה\u0004 — הרי זה דווקא \u0003במילתא דצריכא\u0004 \u0005[בדבר שצריך\u0006\u0005]\u0006 \u0003לה,\u0004 ואולם \u0003במילתא\u0004 \u0005[בדבר\u0006\u0005]\u0006 ש\u0003לא צריכא\u0004 \u0005[צריך\u0006\u0005]\u0006 \u0003לה —\u0004 \u0003לא. דאי\u0004 \u0005[שאם\u0006\u0005]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים\u0006\u0005]\u0006 — \u0003לא משעבד\u0004 \u0005[משועבד\u0006\u0005]\u0006 \u0003לה כלל.\u0004","\u0003אלא היכי דמי\u0004 \u0005[כיצד הוא\u0006 המקרה\u0005]\u0006 \u0003דמשעבד\u0004 \u0005[שמשועבד\u0006\u0005]\u0006 \u0003לה\u0004 לדעת חכמים בקרבן שהיא חייבת — \u0003כגון דאקנייה\u0004 \u0005[שהיקנה\u0006\u0005]\u0006 \u0003לה\u0004 בהמה זו, \u0003וכיון דאקני\u0004 \u0005[שהיקנה\u0006\u0005]\u0006 \u0003לה —\u0004 \u0003הוה דנפשה\u0004 \u0005[הריהו של עצמה\u0006\u0005]\u0006 ונמצאת כמפרישה קרבן מרכושה שלה, ובודאי אין הבהמה יוצאת לחולין, ולא ככתוב במשנה. ואם כן חייבים לומר שמשנתנו היא כר' יהודה."],["\u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר\u0006\u0005]\u0006 שמשנתנו כשיטת \u0003רבנן\u0004 \u0005[חכמים\u0006\u0005],\u0006 ומכל מקום ניתן להבין מדוע אף לשיטתם יוצאת הבהמה לחולין; \u0003כי מקני\u0004 \u0005[כאשר מקנה\u0006\u0005]\u0006 \u0003לה\u0004 בעל את קרבנותיה — הרי זה \u0003נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003במלתא דצריכא\u0004 \u0005[בדבר שצריך\u0006\u0005]\u0006 \u0003לה,\u0004 אבל \u0003במילתא\u0004 \u0005[בדבר\u0006\u0005]\u0006 ש\u0003לא צריכא\u0004 \u0005[צריך\u0006\u0005]\u0006 \u0003לה —\u0004 \u0003לא מקני\u0004 \u0005[מקנה\u0006\u0005]\u0006 \u0003לה.\u0004","שנינו במשנה: \u0003אם שלה היתה בהמתה, חטאת\u0004 — \u0003תמות, ועולה\u0004 — \u0003תקרב.\u0004 ושואלים: \u0003היא\u0004 האשה \u0003מנא\u0004 \u0005[מנין\u0006\u0005]\u0006 \u0003לה\u0004 רכוש משלה? \u0003האמרת\u0004 \u0005[הרי אומר אתה\u0006\u0005]\u0006 ככלל: כל \u0003מה שקנתה אשה קנה בעלה! אמר רב פפא:\u0004 כגון \u0003שקמצתה\u0004 (חסכה אותה) \u0003מעיסתה\u0004 שהיא עושה ומיעטה באכילה, ומכסף זה שהוא שלה קנתה בהמה. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור\u0006\u0005]:\u0006 \u0003דאקני\u0004 \u0005[שהיקנה\u0006\u0005]\u0006 \u0003לה\u0004 את הרכוש אדם \u0003אחר ואמר לה \"\u0004הרי הן לך במתנה \u0003על מנת שאין לבעליך רשות בהן\",\u0004 שבכגון זה אין לבעל זכות בנכסי אשתו.","שנינו במשנה: \u0003\"העולה\u0004 — \u0003תקרב, עולה והשלמים\u0004 — \u0003תקרב\" כו'. אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003שמואל ל\u0004חכם \u0003אבוה בר איהי: לא תיתיב על כרעיך\u0004 \u0005[תשב על רגליך\u0006\u0005]\u0006 \u0003עד דאמרת\u0004 \u0005[שתאמר,\u0006 תפרש\u0005]\u0006 \u0003לי הדא מילתא\u0004 \u0005[דבר זה\u0006\u0005]\u0006 השנוי בברייתא: \u0003ואלו הן ארבעה אילים\u0004 של קרבן נזיר \u0003שאינן טעונין\u0004 קרבן \u0003לחם\u0004 ככל איל נזיר: \u0003שלו, ושלה, ושלאחר המיתה, ושלאחר כפרה\u0004 שכבר נתכפר הנזיר בקרבן אחר.","ומסבירים כל אחד ואחד: \u0003שלה —\u0004 \u0003הא דאמרן\u0004 \u0005[זו שאמרנו\u0006\u0005]\u0006 כעת, בקרבנה של האשה שנדרה לשם נזירות והפרישה מרכושה לקרבנותיה, והיפר לה בעלה. \u0003שלו —\u0004 \u0003דתנן\u0004 \u0005[ש\u0006כן שנינו במשנה\u0005]:\u0006 \u0003האיש מדיר את בנו בנזיר,\u0004 כלומר, שיכול להחיל על בנו הקטן נזירות, \u0003ואין האשה מדרת את בנה בנזיר.\u0004 ואולם, אף שהקטן נעשה נזיר על ידי אביו, מכל מקום אם אינו רוצה בכך (בין מחמת עצמו או מפני אחרים שאומרים לו זאת) — בטלה הנזירות. ולכן, אם \u0003גילח\u0004 הילד את שערו בתוך זמן הנזירות, והוכיח בכך שאינו רוצה להיות נזיר, \u0003או שגילחוהו קרובים,\u0004 ואף אם לא עשה מעשה כגון גילוח, אלא רק \u0003מיחה\u0004 הילד, \u0003או שמיחוהו\u0004 (גרמו לו למחות) \u0003קרובים\u0004 — בטלה נזירותו.","ובמקרה זה, אם \u0003היו לו מעות סתומין\u0004 שהוקדשו לצורך קרבנותיו של ילד זה, ולא נתפרש למה מיועד כל סכום כסף — \u0003יפלו\u0004 כל הכספים \u0003לנדבה,\u0004 להקריב בהם עולות על גבי המזבח. אם היו ה\u0003מעות\u0004 הללו \u0003מפורשין,\u0004 שאמר בפירוש למה מיועד כל מה שבכסף זה, \u0003דמי חטאת —\u0004 \u0003ילכו לים המלח, דמי עולה —\u0004 \u0003יביאו\u0004 תמורתן \u0003עולה, ומועלין בהן. דמי שלמים —\u0004 \u0003יביאו\u0004 תמורתן \u0003שלמים, ונאכלין ליום אחד, ואינן טעונין לחם.\u0004 הרי כאן איל \"שלו\" — של איש, שאין טעון לחם.","איל \u0003שלאחר מיתה מנלן\u0004 \u0005[מנין לנו\u0006\u0005]\u0006 שאינו טעון לחם — \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו במשנה\u0005]:\u0006 \u0003המפריש מעות ל\u0004קרבנות \u0003נזירותו\u0004 ולא פירש לצורך איזה קרבן הם — \u0003לא נהנין\u0004 מהם, שאסור הדבר, \u0003ולא מועלין בהן,\u0004 שאין חייבים קרבן מעילה אם נהנים מהם. ומדוע אין מועלים — \u0003מפני שהן ראויין להביא בכולן שלמים,\u0004 ובשלמים אין דין מעילה אלא לאחר זריקת הדם.","\u0003מת\u0004 המפריש, \u0003והיו לו מעות סתומים,\u0004 שלא פירש לצורך איזה קרבן הם — \u0003יפלו\u0004 כולם \u0003לנדבה.\u0004 ואם היו \u0003מעות מפורשין, דמי חטאת —\u0004 \u0003יוליך לים המלח, לא נהנין ולא מועלין\u0004 בהם. \u0003דמי עולה —\u0004 \u0003יביאו\u0004 תמורתן \u0003עולה, ומועלין בהן. דמי שלמים —\u0004 \u0003יביאו\u0004 תמורתן \u0003שלמים ונאכלין ליום אחד ואינן טעונין לחם.\u0004 הרי איל שלאחר מיתה שאינו טעון לחם.","ובאשר לאיל \u0003שלאחר כפרה,\u0004 שכבר נתכפר הנזיר בקרבן אחר — \u0003סברא הוא,\u0004 אף שלא מצאנו דבר זה מפורש, שכן \u0003שלאחר המיתה מאי\u0004 \u0005[מה\u0006\u0005]\u0006 \u0003טעם\u0004 אין מביאים לחם — לפי ש\u0003לא חזיא\u0004 \u0005[ראוי\u0006\u0005]\u0006 קרבן זה \u0003לכפרה,\u0004 שאין מכפרים על המת, ואם כן \u0003שלאחר כפרה נמי\u0004 \u0005[גם כן\u0006\u0005] —\u0006 \u0003הא לא חזיא\u0004 \u0005[הרי אינו ראוי\u0006\u0005]\u0006 עוד \u0003לכפרה\u0004 שכבר נתכפר בקרבן אחר.","ושואלים: \u0003ותו ליכא\u0004 \u0005[ו\u0006כי אין עוד\u0005]\u0006 קרבן שלמים של נזיר שאינו טעון לחם מלבד ארבעה אלו? \u0003והאיכא\u0004 \u0005[והרי יש\u0006\u0005]\u0006 מה ששנינו: \u0003ושאר כל שלמי נזיר ששחטן שלא כמצותן,\u0004 כגון ששינה בבהמה ולא הביא איל בגיל הראוי — \u0003כשרים\u0004 כקרבן ומותרים באכילה, אבל \u0003לא עולין לבעלים לשום\u0004 (לשם) \u0003חובה\u0004 וחייב להביא קרבן אחר, \u0003ו\u0004אלו \u0003נאכלין ליום אחד\u0004 כשלמי נזיר, \u0003ואינן טעונין לא לחם ולא זרוע\u0004 כשלמי נזיר. הרי שיש דוגמה נוספת לשלמי נזיר בלא לחם!","ומשיבים: ברשימה זו ששנינו, רק קרבנות שהביא \u0003כמצותן קא חשיב\u0004 \u0005[הוא מונה\u0006\u0005],\u0006 אבל קרבנות שהביא \u0003שלא כמצותן לא קא חשיב\u0004 \u0005[מונה\u0006\u0005].\u0006","שנינו לעיל, במי שהפריש מעות לנזירותו ומת: \u0003היו לו מעות סתומים\u0004 — \u0003יפלו לנדבה\u0004"],["\u0003והלא דמי חטאת מעורבין בהן\u0004 במעות הסתומות הללו, וכיצד ילכו כולן לנדבה שכולה עולה? \u0003אמר ר' יוחנן: הלכה\u0004 מקובלת \u0003היא בנזיר\u0004 שמעות סתומות של נזיר הולכות כולן לנדבה, אף שיש בהן דמי חטאת. \u0003ריש לקיש אמר:\u0004 אמר הכתוב \u0003\"לכל נדריהם ולכל נדבותם\u0004 אשר יקריבו לה' לעולה\u0003\"\u0004 (ויקרא כב, יח) \u0003התורה אמרה: מותר נדר יהא לנדבה.\u0004 ואף כאן, כיון שנדר הנזירות הזה איננו יכול לבוא לידי מימוש, שהרי מת האיש — הולכים המעות לנדבה.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003ל\u0004שיטת \u0003ר' יוחנן\u0004 ש\u0003אמר הלכה היא בנזיר —\u0004 \u0003אמטו להכי\u0004 \u0005[משום כך\u0006\u0005]\u0006 אם היו \u0003סתומין —\u0004 \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 ואם היו \u0003מפורשין —\u0004 \u0003לא,\u0004 שכך היא ההלכה. \u0003אלא ל\u0004דעת \u0003ריש לקיש\u0004 הסומך על הכתוב \u0003\"לכל נדריהם ולכל נדבותם\", מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 מעות \u0003סתומין? אפילו\u0004 מעות \u0003מפורשין\u0004 שמת בעליהם ילכו לנדבה!","\u0003אמר רבא: מפורשין לא מצית אמרת\u0004 \u0005[אין אתה יכול לומר\u0006\u0005]\u0006 כי \u0003כבר פסקה\u0004 \u0005[פסק,\u0006 חתך, זאת\u0005]\u0006 ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל,\u0004 שכך דרש על הכתוב המחייב להעלות קדשים לבית המקדש \u0003\"רק קדשיך אשר יהיו לך ונדריך\"\u0004 (דברים יב, כו) — \u0003בולדי קדשים\u0004 (שנולדו לבהמה נקיבה שהפריש לשלמים) \u0003ו\u0004כן \u0003בתמורתם\u0004 (שאמר על בהמת חולין שתהא היא קדושה תמורת בהמת הקדשים) \u0003הכתוב מדבר,\u0004 שאף הם","\u0003מה תקנתן —\u0004 \u0003\"תשא ובאת אל המקום אשר יבחר ה'\"\u0004 (דברים יב, כו). \u0003יכול\u0004 שהכוונה היא רק ש\u0003יעלם לבית הבחירה\u0004 (בית המקדש), שיביא אותם למקום אשר יבחר ה', \u0003ו\u0004אולם לא יקריבם, אלא \u0003ימנע מהם מים ומזון בשביל שימותו —\u0004 \u0003תלמוד לומר: \"ועשית עלתיך הבשר והדם\u0004 על מזבח ה' אלהיך ודם זבחיך ישפך על מזבח ה' אלהיך והבשר תאכל\u0003\"\u0004 (דברים יב, כז),","\u0003לומר לך: כדרך שאתה נוהג בעולה —\u0004 \u0003נהוג\u0004 כמו כן \u0003בתמורתה\u0004 ותעלה אף אותה כליל, ו\u0003כדרך שאתה נוהג בשלמים\u0004 — \u0003נהוג\u0004 כמו כן אף \u0003בולדיהם\u0004 שמקריבים את האימורים והבעלים אוכלים את השאר. \u0003יכול אף ולד חטאת ותמורת אשם\u0004 יהא דינם \u0003כן,\u0004 שינהג בתמורה ובוולד כמו שנוהג בהם, ויקרבו על גבי המזבח — \u0003תלמוד לומר: \"רק\"\u0004 למעט את אלו, אלו \u0003דברי ר' ישמעאל.\u0004","\u0003ר' עקיבא אומר: אינו צריך\u0004 לדרשה זו לענין אשם, ש\u0003הרי הוא אומר \"אשם הוא\"\u0004 (ויקרא ה, יט), לומר: \u0003בהוויתו יהא,\u0004 שרק הוא עצמו כפי שהוא קרב, ולא תמורתו. הרי שבברייתא זו נתבאר במפורש שלא ניתן להביא במותר חטאת קרבן למזבח, ולכן דמים שהופרשו לצורך חטאת נזיר, כיון שמת בעליהם — ילכו לים המלח, ולא לנדבה, ואף להסברו של ריש לקיש.","כיון שהובאה ברייתא זו מבררים אותה לפרטיה. \u0003קתני\u0004 \u0005[שנה\u0006\u0005]:\u0006 \u0003יכול יעלם לבית הבחירה וימנע מהם מים ומזון בשביל שימותו —\u0004 \u0003תלמוד לומר: \"ועשית עלתיך\".\u0004 ושואלים: \u0003אמאי\u0004 \u0005[מדוע\u0006\u0005]\u0006 יעלה על הדעת לעשות כן? \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003ולד חטאת הוא דגמירין\u0004 \u0005[שאנחנו למודים\u0006\u0005]\u0006 \u0003בה\u0004 שהולך ל\u0003מיתה,\u0004 אבל לא בקדשים אחרים, ומדוע צריך לדרוש את הכתוב למעטם? ומשיבים: \u0003אי לאו קרא\u0004 \u0005[אם לא הכתוב\u0006 המפורש\u0005]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר\u0006\u0005]\u0006 כי ההלכה באה ללמד ש\u0003ולד חטאת\u0004 מומת \u0003בכל מקום,\u0004 ואין צריכים להביא אותו דווקא לבית הבחירה כדי להמיתו שם,"],["\u0003ו\u0004אולם \u0003ולדי קדשים\u0004 אחרים מביאים \u0003בבית הבחירה\u0004 ושם ממיתים אותם, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 ש\u0003לא\u0004 ממיתים את וולדי שאר קדשים, ומביאים אותם לקרבן.","ומוסיפים לדון בפרטי הדברים. \u0003קתני\u0004 \u0005[שנה\u0006\u0005]\u0006 שם: \u0003יכול אף ולד חטאת ותמורת אשם כן\u0004 שיקרבו על גבי המזבח — \u0003תלמוד לומר: \"רק\".\u0004 ושואלים: \u0003למה לי קרא\u0004 \u0005[כתוב\u0006\u0005]\u0006 לענין זה? הלא \u0003הילכתא גמירי לה\u0004 \u0005[הלכה\u0006 למשה מסיני למודים אנו אותה\u0005]\u0006 ש\u0003ולד חטאת למיתה אזיל\u0004 \u0005[הולך\u0006\u0005]!\u0006 ומשיבים: \u0003הכי נמי\u0004 \u0005[כך\u0006 הוא גם כן\u0005]\u0006 לענין ולד חטאת, \u0003וקרא\u0004 \u0005[והכתוב\u0006\u0005]\u0006 ללמד \u0003ל\u0004ענין \u0003אשם הוא דאתא\u0004 \u0005[שבא\u0006\u0005].\u0006","ושואלים: \u0003אשם נמי הילכתא גמירי לה\u0004 \u0005[גם כן הלכה\u0006 למשה מסיני למודים אנו אותה\u0005]\u0006 והיא: \u0003כל שאילו בחטאת מתה,\u0004 כלומר, כל קרבן שיש בו פסול כזה שאם היה זה חטאת היה הולך למיתה, ובכלל זה תמורה, אם היה זה \u0003באשם —\u0004 \u0003רועה,\u0004 כלומר, את קרבן האשם הזה משאירים אותו שירעה עד שיפול בו מום ואינו קרב על גבי המזבח. ואם כן, לשם מה אנו צריכים את הלימוד מהמקרא לענין זה?","\u0003אלא\u0004 כך צריך לומר: \u0003אי מהילכתא\u0004 \u0005[אם מן ההלכה\u0006\u0005]\u0006 בלבד הייתי למד, \u0003הוה אמינא:\u0004 \u0005[הייתי אומר\u0006\u0005]:\u0006 \u0003הילכתא\u0004 \u0005[הלכה\u0006\u0005]\u0006 היא שצריך לעשות כך, שוולד חטאת ימות ותמורת אשם תרעה, \u0003ו\u0004אולם \u0003אי אקריביה\u0004 \u0005[אם הקריב אותו\u0006\u0005]\u0006 בכל זאת — \u0003לא ליחייב\u0004 \u0005[יתחייב\u0006\u0005]\u0006 \u0003עליה ולא כלום,\u0004 על כן \u0003קא משמע לן קרא\u0004 \u0005[השמיע לנו הכתוב\u0006\u0005]\u0006 \u0003דאי\u0004 \u0005[שאם\u0006\u0005]\u0006 \u0003מקריב ליה\u0004 \u0005[אותו\u0006\u0005] —\u0006 \u0003קאים עליה\u0004 \u0005[עובר עליו\u0006\u0005]\u0006 \u0003בעשה,\u0004 באיסור הנובע מן המיעוט הכתוב \"רק קדשיך\" (דברים יב, כו).","שנינו באותה ברייתא: \u0003ר' עקיבא אומר אינו צריך\u0004 לימוד מפסוק \"רק קדשיך\" לאשם, \u0003הרי הוא אומר \"אשם הוא\"\u0004 (ויקרא ה, יט) — \u0003בהוייתו יהא.\u0004 ושואלים: \u0003למה לי קרא\u0004 \u0005[כתוב\u0006\u0005]\u0006 לצורך זה? הלא \u0003גמרא גמירין לה\u0004 \u0005[בהלכה למודים\u0006 אנו אותה\u0005]:\u0006 \u0003כל שבחטאת מתה\u0004 — \u0003באשם רועה\u0004 ולכן ברור שבמקרה זה אין מקריבים אותו!","ומשיבים: \u0003הכי נמי\u0004 \u0005[כך\u0006 הוא גם כן\u0005],\u0006 \u0003וכי אתא קרא\u0004 \u0005[וכאשר בא הכתוב\u0006\u0005] —\u0006 \u0003ל\u0004צורך ענין אחר שאמר \u0003רב\u0004 הוא שבא. ש\u0003אמר רב הונא אמר רב:\u0004 קרבן \u0003אשם שניתק לרעייה,\u0004 כלומר, שפסקו דינו שילך לרעיה, שאי אפשר להקריבו כקרבן אשם, ודינו שירעה עד שיפול בו מום ואז יימכר ויביא בדמיו עולה כנדבה, ועבר \u0003ושחטו\u0004 אותו עצמו (ולא את הבהמה שקונים בדמיו), אם שחטו \u0003לשם עולה —\u0004 \u0003כשר.\u0004","ויש לדייק בדברי רב: \u0003טעמא\u0004 \u0005[הטעם,\u0006 מדובר דווקא\u0005]\u0006 באשם ש\u0003ניתק\u0004 לרעיה, \u0003הא\u0004 \u0005[הרי,\u0006 אבל\u0005]\u0006 אם \u0003לא ניתק\u0004 לרעיה — \u0003לא,\u0004 וסתם אשם שהקריבו אותו לעולה — פסול. ש\u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 \"אשם \u0003הוא\"\u0004 — כלומר, \u0003בהוייתו יהא\u0004 ולא כקרבן אחר, ואם הקריבו כקרבן אחר — פסול.","וחוזרים לענין קרבנות נזיר. \u0003אמר מר\u0004 \u0005[החכם\u0006\u0005]\u0006 ר' יוחנן: \u0003הלכה היא בנזיר\u0004 שמעות סתומים שלו שיש בהם גם דמי חטאת ילכו לנדבה. ושואלים: מלשונו משמע שדווקא בנזיר ישנה הלכה זו \u0003ותו ליכא\u0004 \u0005[ו\u0006כי אין עוד\u0005]\u0006 דברים שיש בהם הלכה כזו, ולא רק בנזיר? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ושאר חייבי קינין שבתורה,\u0004 כלומר, אלה שנתחייבו להביא קרבן עוף בלבד אם היו עניים, כגון מצורע, שמביא שני תורים אחד לעולה ואחד לחטאת במקום כבש וכבשה,"]]};
